import { afterEach, describe, expect, it, vi } from 'vitest';

// The base URL is read once when the module loads, so each case loads a fresh copy.
async function load(env: { VITE_API_BASE_URL?: string; DEV: boolean }) {
  vi.resetModules();
  vi.stubEnv('VITE_API_BASE_URL', env.VITE_API_BASE_URL ?? '');
  vi.stubEnv('DEV', env.DEV);
  return import('./apiBaseUrl');
}

afterEach(() => {
  vi.unstubAllEnvs();
  vi.unstubAllGlobals();
});

describe('API base URL', () => {
  it('uses the configured URL, without a trailing slash, and joins paths with exactly one slash', async () => {
    const api = await load({ VITE_API_BASE_URL: 'https://api.example.test/', DEV: false });
    expect(api.getApiBaseUrl()).toBe('https://api.example.test');
    expect(api.apiUrl('/programs')).toBe('https://api.example.test/programs');
    expect(api.apiUrl('programs')).toBe('https://api.example.test/programs');
  });

  it('refuses to build a request URL in a production build with no URL configured', async () => {
    const api = await load({ DEV: false });
    expect(api.API_BASE_URL).toBeUndefined();
    expect(() => api.getApiBaseUrl()).toThrow('VITE_API_BASE_URL must be set for frontend API requests.');
  });

  it('in development, points at port 3000 on the page host, bracketing IPv6', async () => {
    vi.stubGlobal('location', { ...window.location, hostname: 'console.local.test' });
    expect((await load({ DEV: true })).getApiBaseUrl()).toBe('http://console.local.test:3000');
    vi.stubGlobal('location', { ...window.location, hostname: '::1' });
    expect((await load({ DEV: true })).getApiBaseUrl()).toBe('http://[::1]:3000');
    vi.stubGlobal('location', { ...window.location, hostname: '' });
    expect((await load({ DEV: true })).getApiBaseUrl()).toBe('http://127.0.0.1:3000');
  });

  it('in development outside a browser, falls back to the loopback address', async () => {
    vi.stubGlobal('window', undefined);
    expect((await load({ DEV: true })).getApiBaseUrl()).toBe('http://127.0.0.1:3000');
  });
});

import { describe, expect, it } from 'vitest';
import {
  formatTakePresetDbInputValue,
  getMixerChannelById,
  isEditableTarget,
  normalizeMixerChannelsPayload,
  normalizeProgramAudioMeter,
  normalizeProgramSongPlayback,
  normalizeSceneInstantPlayback,
  normalizeSlideshowImageList,
  normalizeTakeVolumeFadeMs,
  normalizeTakeVolumePresetDb,
  normalizeUpdateVersion,
  parseMixerLevelInputToFader,
  parseSceneMetadata,
  readControlUpdateVersion,
  reconcileProgramSongPlayback,
  resolveControlUpdateTopicFromType,
  withIndependentProgramClockMetadata
} from './broadcast';

describe('editable targets', () => {
  it('treats form fields and editable content as editable, and anything else as not', () => {
    expect(isEditableTarget(null)).toBe(false);
    expect(isEditableTarget(document.createElement('input'))).toBe(true);
    expect(isEditableTarget(document.createElement('textarea'))).toBe(true);
    expect(isEditableTarget(document.createElement('select'))).toBe(true);
    expect(isEditableTarget(document.createElement('div'))).toBe(false);
    const editable = document.createElement('div');
    Object.defineProperty(editable, 'isContentEditable', { value: true });
    expect(isEditableTarget(editable)).toBe(true);
  });
});

describe('take volume presets', () => {
  it('accepts numeric strings and falls back on anything unreadable', () => {
    expect(normalizeTakeVolumePresetDb('-12', -15)).toBe(-12);
    expect(normalizeTakeVolumePresetDb('loud', -15)).toBe(-15);
    expect(normalizeTakeVolumeFadeMs('250.6', 500)).toBe(251);
    expect(normalizeTakeVolumeFadeMs(undefined, 500)).toBe(500);
    expect(normalizeTakeVolumeFadeMs(99999, 500)).toBe(20000);
    expect(formatTakePresetDbInputValue(-6)).toBe('-6.0');
    expect(formatTakePresetDbInputValue(Number.NaN)).toBe('-15.0');
  });
});

describe('mixer channels', () => {
  const fallback = [{ id: 'song', name: 'Song', volume: 0.8, muted: true, solo: false }];

  it('keeps the fallback values for fields a payload leaves out, and skips unreadable items', () => {
    expect(
      normalizeMixerChannelsPayload(
        [null, [], 'song', { id: 3 }, { id: '  ' }, { id: 'song', name: '  ' }, { id: ' extra ' }],
        fallback
      )
    ).toEqual([
      { id: 'song', name: 'Song', volume: 0.8, muted: true, solo: false },
      { id: 'extra', name: 'extra', volume: 1, muted: false, solo: false }
    ]);
  });

  it('returns a neutral channel for an unknown id', () => {
    expect(getMixerChannelById(fallback, 'stream')).toEqual({
      id: 'stream',
      name: 'stream',
      volume: 1,
      muted: false,
      solo: false
    });
  });

  it('reads typed levels, treating blank input as unchanged', () => {
    expect(parseMixerLevelInputToFader('   ', 0.4)).toBe(0.4);
    expect(parseMixerLevelInputToFader('-inf', 0.4)).toBe(0);
    expect(parseMixerLevelInputToFader('quiet', 0.4)).toBe(0.4);
    expect(parseMixerLevelInputToFader('0 dB', 0.4)).toBeGreaterThan(0);
  });
});

describe('playback payloads', () => {
  it('returns silent meters and idle playback for a missing payload', () => {
    const meter = normalizeProgramAudioMeter(null);
    expect(meter.updatedAt).toBe(new Date(0).toISOString());
    expect(normalizeProgramAudioMeter({}).updatedAt).not.toBe(new Date(0).toISOString());
    expect(normalizeProgramAudioMeter({ updatedAt: 'then' }).updatedAt).toBe('then');
    expect(normalizeProgramSongPlayback(undefined)).toMatchObject({ token: '', isPlaying: false, durationMs: null });
    expect(normalizeSceneInstantPlayback(0)).toMatchObject({ sceneId: null, instantName: '' });
  });

  it('reads song playback fields and drops malformed ones', () => {
    const full = normalizeProgramSongPlayback({
      token: 't',
      audioUrl: 'https://media.example.test/a.mp3',
      currentTimeMs: 5000,
      durationMs: 4000,
      updatedAt: 'now',
      telemetryStale: true,
      introStatus: 'playing',
      introFailureReason: '  slow  ',
      queueEntryId: ' q1 '
    });
    expect(full).toMatchObject({
      currentTimeMs: 4000,
      durationMs: 4000,
      updatedAt: 'now',
      telemetryStale: true,
      introStatus: 'playing',
      introFailureReason: 'slow',
      queueEntryId: 'q1'
    });
    const sparse = normalizeProgramSongPlayback({ token: 1, audioUrl: 2, introStatus: 'weird', introFailureReason: '   ', queueEntryId: '  ' });
    expect(sparse).toMatchObject({ token: '', audioUrl: '', introStatus: 'none', introFailureReason: null, queueEntryId: null });
    expect(sparse.telemetryStale).toBeUndefined();
    for (const status of ['pending', 'completed', 'degraded'] as const) {
      expect(normalizeProgramSongPlayback({ introStatus: status }).introStatus).toBe(status);
    }
  });

  it('reads a scene instant from the nested instant or the top level', () => {
    expect(
      normalizeSceneInstantPlayback({ sceneId: 2, instant: { id: 5, assetId: ' a-1 ', name: 'Bell' }, updatedAt: 'now' })
    ).toMatchObject({ sceneId: 2, instantId: 5, mediaAssetId: 'a-1', instantName: 'Bell', updatedAt: 'now' });
    expect(normalizeSceneInstantPlayback({ instant: [], mediaAssetId: '  ' })).toMatchObject({
      instantId: null,
      mediaAssetId: null,
      instantName: ''
    });
  });

  it('keeps the previous position when the same playing song jumps backwards too far', () => {
    const prev = normalizeProgramSongPlayback({ token: 't', audioUrl: 'u', isPlaying: true, currentTimeMs: 60000 });
    const back = normalizeProgramSongPlayback({ token: 't', audioUrl: 'u', isPlaying: true, currentTimeMs: 0 });
    const close = normalizeProgramSongPlayback({ token: 't', audioUrl: 'u', isPlaying: true, currentTimeMs: 59999 });
    expect(reconcileProgramSongPlayback(prev, back)).toBe(prev);
    expect(reconcileProgramSongPlayback(prev, close)).toBe(close);
    expect(reconcileProgramSongPlayback({ ...prev, isPlaying: false }, back)).toBe(back);
    expect(reconcileProgramSongPlayback(prev, { ...back, audioUrl: 'other' })).toEqual({ ...back, audioUrl: 'other' });
    expect(reconcileProgramSongPlayback(prev, { ...back, token: 'other' })).toEqual({ ...back, token: 'other' });
  });
});

describe('control update topics and versions', () => {
  it('maps every update type to its topic', () => {
    expect(resolveControlUpdateTopicFromType(4)).toBeNull();
    expect(resolveControlUpdateTopicFromType('flight_update')).toBe('flight');
    expect(resolveControlUpdateTopicFromType('song_off_air')).toBe('songPlayback');
    expect(resolveControlUpdateTopicFromType('nothing')).toBeNull();
  });

  it('reads the version from the top level, then the topic-specific place', () => {
    expect(normalizeUpdateVersion(-1)).toBeNull();
    expect(normalizeUpdateVersion('2.7')).toBe(2);
    expect(readControlUpdateVersion('state', null)).toBeNull();
    expect(readControlUpdateVersion('state', [])).toBeNull();
    expect(readControlUpdateVersion('state', { version: 4 })).toBe(4);
    expect(readControlUpdateVersion('state', { stateVersion: 3 })).toBe(3);
    expect(readControlUpdateVersion('audioBus', { settings: { version: 2 } })).toBe(2);
    expect(readControlUpdateVersion('audioMeter', { audioMeterVersion: 6 })).toBe(6);
    expect(readControlUpdateVersion('songPlayback', { playback: { version: 7 } })).toBe(7);
    expect(readControlUpdateVersion('sceneInstant', { sceneInstantVersion: 8 })).toBe(8);
    expect(readControlUpdateVersion('flight', { flightVersion: 9 })).toBe(9);
    expect(readControlUpdateVersion('other' as never, { flightVersion: 9 })).toBeNull();
  });
});

describe('slideshow and scene metadata', () => {
  it('splits a comma or newline list given as a string, and ignores other values', () => {
    expect(normalizeSlideshowImageList('a.jpg, b.jpg\na.jpg')).toEqual(['a.jpg', 'b.jpg']);
    expect(normalizeSlideshowImageList(['a.jpg', 3])).toEqual(['a.jpg']);
    expect(normalizeSlideshowImageList(7)).toEqual([]);
  });

  it('reads an object, and returns an empty one for anything else', () => {
    expect(parseSceneMetadata('{"a":1}')).toEqual({ a: 1 });
    expect(parseSceneMetadata(null)).toEqual({});
    expect(parseSceneMetadata('[1]')).toEqual({});
    expect(parseSceneMetadata('null')).toEqual({});
    expect(parseSceneMetadata('{bad')).toEqual({});
  });

  it('passes program clock metadata through unchanged', () => {
    const metadata = { clock: { mode: 'local' } };
    expect(withIndependentProgramClockMetadata(metadata)).toBe(metadata);
  });
});

import { describe, expect, it } from 'vitest';
import { matchChartEntry } from './chartFeed';

describe('chart entry matching', () => {
  const lookup = { byId: { 'c-1': 'by id' }, byKey: { 'modugno volare': 'by text' } };

  it('prefers the chart id, then the chyron text, and finds nothing for unknown or blank input', () => {
    expect(matchChartEntry(lookup, { id: ' c-1 ', text: 'Modugno — Volare' })).toBe('by id');
    expect(matchChartEntry(lookup, { id: 'missing', text: 'Modugno - Volare!' })).toBe('by text');
    expect(matchChartEntry(lookup, { id: null, text: 'Someone else' })).toBeNull();
    expect(matchChartEntry(lookup, { text: '   ' })).toBeNull();
    expect(matchChartEntry(null, { id: 'c-1' })).toBeNull();
  });
});

import { act, renderHook } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';

const preferences = vi.hoisted(() => ({
  profile: { selectedProgramId: 'main', transitions: {} as Record<string, string> },
  updateProfile: vi.fn(),
}));
vi.mock('../contexts/ConsolePreferencesContext', () => ({
  useConsolePreferences: () => preferences,
}));

import { useGlobalProgramId } from './globalProgram';
import { useGlobalTransitionId } from './globalTransition';

beforeEach(() => {
  preferences.profile = { selectedProgramId: 'evening', transitions: { evening: 'soft-cut' } };
  preferences.updateProfile = vi.fn();
});

describe('the operator selected program', () => {
  it('reads the saved program and saves a trimmed choice, falling back to main when blank', () => {
    const { result } = renderHook(() => useGlobalProgramId());
    expect(result.current[0]).toBe('evening');
    act(() => result.current[1]('  late-show  '));
    expect(preferences.updateProfile).toHaveBeenLastCalledWith({ selectedProgramId: 'late-show' });
    act(() => result.current[1]('   '));
    expect(preferences.updateProfile).toHaveBeenLastCalledWith({ selectedProgramId: 'main' });
  });
});

describe('the per-program transition', () => {
  it('reads the saved transition for the program and keeps the others when one changes', () => {
    preferences.profile.transitions = { evening: 'soft-cut', main: 'wipe' };
    const { result } = renderHook(() => useGlobalTransitionId(' evening '));
    expect(result.current[0]).toBe('soft-cut');
    act(() => result.current[1](' flash '));
    expect(preferences.updateProfile).toHaveBeenLastCalledWith({
      transitions: { evening: 'flash', main: 'wipe' },
    });
    act(() => result.current[1]('  '));
    expect(preferences.updateProfile).toHaveBeenLastCalledWith({
      transitions: { evening: 'crescendo-prism', main: 'wipe' },
    });
  });

  it('uses the default transition and the main program when nothing is saved or the id is blank', () => {
    preferences.profile.transitions = {};
    expect(renderHook(() => useGlobalTransitionId('  ')).result.current[0]).toBe('crescendo-prism');
    expect(renderHook(() => useGlobalTransitionId()).result.current[0]).toBe('crescendo-prism');
  });
});

import { describe, expect, it } from 'vitest';
import {
  applyModoItalianoBracketAdvancement,
  createDefaultModoItalianoBracketMatches,
  drawModoItalianoBracketOpeningSongs,
  fillNextModoItalianoBracketOpeningSlot,
  normalizeModoItalianoBracketDrawCommand,
  normalizeModoItalianoBracketMatches,
  normalizeModoItalianoBracketSongPoolIds
} from './modoItalianoBracket';

describe('bracket song pool', () => {
  it('keeps positive integer ids once, from numbers or strings, limited to the catalogue', () => {
    expect(normalizeModoItalianoBracketSongPoolIds('1,2')).toEqual([]);
    expect(normalizeModoItalianoBracketSongPoolIds([1, '2', 2, 0, -1, 1.5, 'x', null])).toEqual([1, 2]);
    expect(normalizeModoItalianoBracketSongPoolIds([1, 2, 3], new Set([2, 3]))).toEqual([2, 3]);
  });
});

describe('bracket draw command', () => {
  it('rejects anything without a numeric id and start time', () => {
    expect(normalizeModoItalianoBracketDrawCommand(null)).toBeNull();
    expect(normalizeModoItalianoBracketDrawCommand([])).toBeNull();
    expect(normalizeModoItalianoBracketDrawCommand({ id: '1', startedAt: 0 })).toBeNull();
    expect(normalizeModoItalianoBracketDrawCommand({ id: 1 })).toBeNull();
  });

  it('normalises the seed, duration, pool and selected song', () => {
    expect(
      normalizeModoItalianoBracketDrawCommand({ id: 1, startedAt: 10, seed: '7.9', durationSeconds: '3.5', songIds: [4, '5'], selectedSongId: 5 })
    ).toEqual({ id: 1, seed: 7, startedAt: 10, durationSeconds: 3, songIds: [4, 5], selectedSongId: 5 });
    expect(normalizeModoItalianoBracketDrawCommand({ id: 2, startedAt: 0, seed: -1, durationSeconds: 'x' })).toEqual({
      id: 2,
      seed: 5,
      startedAt: 0,
      durationSeconds: 5,
      songIds: [],
      selectedSongId: null
    });
  });
});

describe('bracket match normalization', () => {
  it('ignores malformed matches and out-of-range ids, and clears non-numeric fields', () => {
    const matches = normalizeModoItalianoBracketMatches([
      null,
      'x',
      { id: 0, songAId: 1 },
      { id: 16, songAId: 1 },
      { id: '1', songAId: 1 },
      { id: 1, songAId: 3, songBId: '4', winnerId: 'x' }
    ]);
    expect(matches[0]).toEqual({ id: 1, songAId: 3, songBId: null, winnerId: null });
    expect(matches).toHaveLength(15);
  });

  it('drops repeated opening songs and winners that are not in their match, and advances winners', () => {
    const matches = createDefaultModoItalianoBracketMatches();
    matches[0] = { id: 1, songAId: 1, songBId: 2, winnerId: 2 };
    matches[1] = { id: 2, songAId: 1, songBId: 2, winnerId: 9 };
    const advanced = applyModoItalianoBracketAdvancement(matches);
    expect(advanced[1]).toEqual({ id: 2, songAId: null, songBId: null, winnerId: null });
    expect(advanced[8]).toMatchObject({ id: 9, songAId: 2, songBId: null });
  });

  it('starts at the quarterfinals, ignoring round-of-16 matches', () => {
    const matches = createDefaultModoItalianoBracketMatches();
    matches[0] = { id: 1, songAId: 1, songBId: 2, winnerId: 1 };
    matches[8] = { id: 9, songAId: 3, songBId: 4, winnerId: 4 };
    const advanced = applyModoItalianoBracketAdvancement(matches, 'quarterfinals');
    expect(advanced[8]).toMatchObject({ songAId: 3, songBId: 4 });
    expect(advanced[12]).toMatchObject({ id: 13, songAId: 4 });
  });
});

describe('bracket opening draw', () => {
  it('draws one unused song into the first empty slot', () => {
    const matches = createDefaultModoItalianoBracketMatches();
    matches[0] = { id: 1, songAId: 1, songBId: null, winnerId: null };
    const result = drawModoItalianoBracketOpeningSongs(matches, 'roundOf16', [1, 2], 3);
    expect(result).toMatchObject({ drawnSongIds: [2], availableSongIds: [2], emptySlotCount: 15, availableSongCount: 1 });
    expect(result.matches[0]).toMatchObject({ songAId: 1, songBId: 2 });
  });

  it('draws nothing when every opening slot is filled', () => {
    const matches = createDefaultModoItalianoBracketMatches();
    [9, 10, 11, 12].forEach((id, index) => {
      matches[id - 1] = { id, songAId: index * 2 + 1, songBId: index * 2 + 2, winnerId: null };
    });
    const result = drawModoItalianoBracketOpeningSongs(matches, 'quarterfinals', [20, 21], 'seed');
    expect(result).toMatchObject({ drawnSongIds: [], emptySlotCount: 0, availableSongCount: 2 });
  });
});

describe('filling the next opening slot', () => {
  it('ignores an invalid or already used song and a full bracket, and fills the first empty slot otherwise', () => {
    const matches = createDefaultModoItalianoBracketMatches();
    matches[8] = { id: 9, songAId: 1, songBId: null, winnerId: null };
    expect(fillNextModoItalianoBracketOpeningSlot(matches, 'quarterfinals', 'x')[8].songBId).toBeNull();
    expect(fillNextModoItalianoBracketOpeningSlot(matches, 'quarterfinals', 1)[8].songBId).toBeNull();
    expect(fillNextModoItalianoBracketOpeningSlot(matches, 'quarterfinals', '2')[8].songBId).toBe(2);

    const full = createDefaultModoItalianoBracketMatches();
    [9, 10, 11, 12].forEach((id, index) => {
      full[id - 1] = { id, songAId: index * 2 + 1, songBId: index * 2 + 2, winnerId: null };
    });
    expect(fillNextModoItalianoBracketOpeningSlot(full, 'quarterfinals', 30)).toEqual(normalizeModoItalianoBracketMatches(full, 'quarterfinals'));
  });
});

import { afterEach, describe, expect, it, vi } from 'vitest';
import type { FlightCue } from '../models/broadcast';
import {
  createFlightCue,
  getFlightCueDisplayLabel,
  normalizeFlightCue,
  normalizeFlightSequence
} from './programFlightSequence';

describe('flight cue normalization', () => {
  it('rejects non-objects and unknown kinds', () => {
    expect(normalizeFlightCue(null)).toBeNull();
    expect(normalizeFlightCue([])).toBeNull();
    expect(normalizeFlightCue({ kind: 7 })).toBeNull();
    expect(normalizeFlightCue({ kind: 'explode' })).toBeNull();
  });

  it('keeps every recognised field, trimmed and rounded', () => {
    const cue = normalizeFlightCue({
      id: ' cue-1 ',
      kind: 'scene',
      label: '  Opening  ',
      isFiller: true,
      clockOffsetSeconds: 12.4,
      voiceTrackInstantId: 9.6,
      voiceDuckGain: 0.35,
      voiceFadeInSeconds: 1.5,
      voiceFadeOutSeconds: 2,
      sceneId: 4,
      transitionId: ' fade ',
      songId: 11,
      durationMs: 2500.2,
      metadataPatch: { headline: 'x' },
      instantId: 3,
      mixerChange: { channelId: 'song', volume: 1, muted: true, solo: false }
    });
    expect(cue).toEqual({
      id: 'cue-1',
      kind: 'scene',
      label: 'Opening',
      isFiller: true,
      clockOffsetSeconds: 12,
      voiceTrackInstantId: 10,
      voiceDuckGain: 0.35,
      voiceFadeInSeconds: 1.5,
      voiceFadeOutSeconds: 2,
      sceneId: 4,
      transitionId: 'fade',
      songId: 11,
      durationMs: 2500,
      metadataPatch: { headline: 'x' },
      instantId: 3,
      mixerChange: { channelId: 'song', volume: 1, muted: true, solo: false }
    });
  });

  it('drops invalid optional fields and generates an id when none is given', () => {
    const cue = normalizeFlightCue({
      id: '   ',
      kind: 'mixer',
      label: '   ',
      isFiller: 'yes',
      clockOffsetSeconds: Number.NaN,
      voiceDuckGain: Number.POSITIVE_INFINITY,
      sceneId: '4',
      transitionId: 5,
      durationMs: -1,
      metadataPatch: ['x'],
      mixerChange: { channelId: 'nowhere', volume: 'loud', muted: 'no', solo: 1 }
    });
    expect(cue?.id).toMatch(/^cue_/);
    expect(cue).toEqual({ id: cue?.id, kind: 'mixer', label: undefined, mixerChange: {} });
  });
});

describe('flight sequence normalization', () => {
  afterEach(() => vi.useRealTimers());

  it('rejects non-objects', () => {
    expect(normalizeFlightSequence('sequence')).toBeNull();
  });

  it('keeps valid fields and drops invalid cues', () => {
    const sequence = normalizeFlightSequence({
      id: 7,
      name: 'Morning',
      items: [{ id: 'a', kind: 'wait', durationMs: 10 }, { kind: 'bogus' }],
      loop: true,
      isRunning: true,
      activeItemId: 'a',
      scheduledAt: '2026-11-21T08:00:00Z',
      publishedAt: '2026-11-21T07:00:00Z',
      lastStartedAt: '2026-11-21T08:00:01Z',
      revision: 3,
      createdAt: '2026-11-20T00:00:00Z',
      updatedAt: '2026-11-21T00:00:00Z'
    });
    expect(sequence).toEqual({
      id: 7,
      name: 'Morning',
      items: [{ id: 'a', kind: 'wait', label: undefined, durationMs: 10 }],
      loop: true,
      isRunning: true,
      activeItemId: 'a',
      scheduledAt: '2026-11-21T08:00:00Z',
      publishedAt: '2026-11-21T07:00:00Z',
      lastStartedAt: '2026-11-21T08:00:01Z',
      revision: 3,
      createdAt: '2026-11-20T00:00:00Z',
      updatedAt: '2026-11-21T00:00:00Z'
    });
  });

  it('fills defaults for missing or malformed fields', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-11-21T12:00:00Z'));
    expect(
      normalizeFlightSequence({ id: Number.NaN, name: 3, items: 'none', activeItemId: 4, revision: 1.5 })
    ).toEqual({
      id: 0,
      name: 'Unnamed',
      items: [],
      loop: false,
      isRunning: false,
      activeItemId: null,
      scheduledAt: null,
      publishedAt: null,
      lastStartedAt: null,
      revision: 1,
      createdAt: '2026-11-21T12:00:00.000Z',
      updatedAt: '2026-11-21T12:00:00.000Z'
    });
    expect(normalizeFlightSequence({ activeItemId: null })?.activeItemId).toBeNull();
  });
});

describe('new flight cues', () => {
  it('gives a wait three seconds, a scene a cut, and other kinds nothing extra', () => {
    expect(createFlightCue()).toMatchObject({ kind: 'wait', durationMs: 3000 });
    expect(createFlightCue('scene')).toMatchObject({ kind: 'scene', transitionId: 'cut' });
    const stop = createFlightCue('stopSong');
    expect(Object.keys(stop).sort()).toEqual(['id', 'kind']);
  });
});

describe('flight cue labels', () => {
  const context = {
    scenes: [{ id: 1, name: 'Studio' }],
    songs: [{ id: 2, title: 'Volare', artist: 'Modugno' }],
    instants: [{ id: 3, name: 'Applause' }]
  };
  const label = (cue: Partial<FlightCue>, withContext = true) =>
    getFlightCueDisplayLabel({ id: 'c', kind: 'wait', ...cue } as FlightCue, withContext ? context : undefined);

  it('prefers an explicit label', () => {
    expect(label({ kind: 'scene', label: 'Custom' })).toBe('Custom');
  });

  it('names scenes, songs and instants from the context, else by id, else generically', () => {
