import {
  countSequenceLeafItems,
  getToniChyronContentMode,
  getToniChyronSequenceSelectedItemId,
  normalizeToniChyronSequence,
  resolveToniChyronContent,
  resolveToniChyronLeaf,
  type ToniChyronSequence
} from './toniChyronSequence';

const nest = (depth: number): unknown =>
  depth === 0
    ? { items: [{ id: 'leaf', text: 'deep' }] }
    : { items: [{ id: `n${depth}`, kind: 'sequence', label: `L${depth}`, sequence: nest(depth - 1) }] };

describe('chyron sequence normalization', () => {
  it('rejects non-objects and drops sequences nested too deeply', () => {
    expect(normalizeToniChyronSequence([])).toBeNull();
    expect(normalizeToniChyronSequence({}, 9)).toBeNull();
    expect(countSequenceLeafItems(normalizeToniChyronSequence(nest(8)))).toBe(1);
    expect(countSequenceLeafItems(normalizeToniChyronSequence(nest(9)))).toBe(0);
    expect(countSequenceLeafItems(null)).toBe(0);
  });

  it('reads leaves from text or label and keeps chart fields, dropping malformed ones', () => {
    const sequence = normalizeToniChyronSequence({
      mode: 'autoplay',
      items: [
        'x',
        { id: 'a', text: 'Hit', earoneSongId: ' e-1 ', earoneRank: ' 2 ', earoneSpins: ' 30 ' },
        { text: '  ', label: 'Fallback', earoneSongId: 5, earoneSpins: 6 },
        { text: 7, earoneSongId: Number.NaN, earoneRank: '  ', earoneSpins: Number.POSITIVE_INFINITY },
        { kind: 'sequence', label: '  ', sequence: { items: [] } },
        { kind: 'sequence', id: 'n', label: 'Block', sequence: { items: [{ id: 'b', text: 'B' }] } },
        { kind: 'sequence', sequence: 'broken' }
      ],
      activeItemId: 'n',
      intervalMs: 1500.7,
      startedAt: 10
    })!;
    expect(sequence).toMatchObject({ mode: 'autoplay', activeItemId: 'n', intervalMs: 1500, loop: true, startedAt: 10 });
    expect(sequence.items).toHaveLength(5);
    expect(sequence.items[0]).toMatchObject({ id: 'a', text: 'Hit', earoneSongId: 'e-1', earoneRank: '2', earoneSpins: '30' });
    expect(sequence.items[1]).toMatchObject({ text: 'Fallback', earoneSongId: '5', earoneSpins: '6' });
    expect(sequence.items[1].id).toMatch(/^preset_/);
    expect(sequence.items[2]).toMatchObject({ text: '', earoneSongId: undefined, earoneRank: undefined, earoneSpins: undefined });
    expect(sequence.items[3]).toMatchObject({ kind: 'sequence', label: 'Nested Sequence' });
    expect(sequence.items[3].id).toMatch(/^sequence_/);
    expect(countSequenceLeafItems(sequence)).toBe(4);
    expect(normalizeToniChyronSequence({ items: 'none', loop: 0 })).toMatchObject({ items: [], activeItemId: null, loop: false, mode: 'manual' });
  });
});

describe('chyron content mode', () => {
  it('uses the stated mode, else a sequence when one exists', () => {
    const sequence = normalizeToniChyronSequence({ items: [] });
    expect(getToniChyronContentMode('text', sequence)).toBe('text');
    expect(getToniChyronContentMode('sequence', null)).toBe('sequence');
    expect(getToniChyronContentMode(undefined, sequence)).toBe('sequence');
    expect(getToniChyronContentMode(undefined, null)).toBe('text');
  });
});

describe('chyron selection', () => {
  const items = ['a', 'b', 'c'].map((id) => ({ id, kind: 'preset' as const, text: id.toUpperCase() }));
  const base: ToniChyronSequence = { mode: 'autoplay', items, activeItemId: 'a', intervalMs: 1000, loop: true, startedAt: 0 };

  it('selects nothing for an empty sequence and holds the item in manual mode', () => {
    expect(getToniChyronSequenceSelectedItemId({ ...base, items: [] }, 0)).toBeNull();
    expect(getToniChyronSequenceSelectedItemId({ ...base, mode: 'manual', activeItemId: 'c' }, 99999)).toBe('c');
    expect(getToniChyronSequenceSelectedItemId({ ...base, mode: 'manual', activeItemId: 'zz' }, 99999)).toBe('a');
  });

  it('advances by interval, wrapping when looping and stopping on the last item otherwise', () => {
    expect(getToniChyronSequenceSelectedItemId(base, 4500)).toBe('b');
    expect(getToniChyronSequenceSelectedItemId({ ...base, loop: false }, 4500)).toBe('c');
    expect(getToniChyronSequenceSelectedItemId({ ...base, loop: false }, 1500)).toBe('b');
    expect(getToniChyronSequenceSelectedItemId({ ...base, startedAt: undefined, intervalMs: undefined }, 4500)).toBe('a');
  });
});

describe('chyron resolution', () => {
  const sequence = {
    items: [{ id: 'n', kind: 'sequence', label: 'Chart', sequence: { items: [{ id: 'x', text: 'Number one', useMarquee: true, earoneRank: '1' }] } }]
  };

  it('resolves the active leaf of a nested sequence with its path and chart fields', () => {
    expect(resolveToniChyronContent({ sequence }, 0)).toEqual({
      text: 'Number one',
      useMarquee: true,
      source: 'sequence',
      activePathLabels: ['Chart', 'Number one']
    });
    expect(resolveToniChyronLeaf({ sequence }, 0)).toMatchObject({ text: 'Number one', earoneRank: '1', activePathLabels: ['Chart', 'Number one'] });
  });

  it('falls back to the plain text, and resolves no leaf, without a usable sequence', () => {
    expect(resolveToniChyronContent({ text: 'Plain', useMarquee: true })).toEqual({ text: 'Plain', useMarquee: true, source: 'text', activePathLabels: [] });
    expect(resolveToniChyronContent({ sequence: { items: [] } })).toEqual({ text: '', useMarquee: false, source: 'text', activePathLabels: [] });
    expect(resolveToniChyronContent({ contentMode: 'text', sequence })).toMatchObject({ source: 'text' });
    expect(resolveToniChyronLeaf({})).toBeNull();
    expect(resolveToniChyronLeaf({ contentMode: 'text', sequence })).toBeNull();
    expect(resolveToniChyronLeaf({ sequence: { items: [] } })).toBeNull();
  });
});

export interface ModoItalianoBracketMatch {
  id: number;
  songAId: number | null;
  songBId: number | null;
  winnerId: number | null;
}

export type ModoItalianoBracketStartRound = 'roundOf16' | 'quarterfinals';

export interface ModoItalianoBracketDrawCommand {
  id: number;
  seed: number;
  startedAt: number;
  durationSeconds: number;
  songIds: number[];
  selectedSongId: number | null;
}

export interface ModoItalianoBracketDrawResult {
  matches: ModoItalianoBracketMatch[];
  drawnSongIds: number[];
  availableSongIds: number[];
  emptySlotCount: number;
  availableSongCount: number;
}

const MATCH_COUNT = 15;
const ROUND_OF_16_OPENING_MATCH_IDS = [1, 2, 3, 4, 5, 6, 7, 8];
const QUARTERFINAL_OPENING_MATCH_IDS = [9, 10, 11, 12];

const ADVANCEMENT_TARGETS: Record<number, { matchId: number; slot: 'songAId' | 'songBId' }> = {
  1: { matchId: 9, slot: 'songAId' },
  2: { matchId: 9, slot: 'songBId' },
  3: { matchId: 10, slot: 'songAId' },
  4: { matchId: 10, slot: 'songBId' },
  5: { matchId: 11, slot: 'songAId' },
  6: { matchId: 11, slot: 'songBId' },
  7: { matchId: 12, slot: 'songAId' },
  8: { matchId: 12, slot: 'songBId' },
  9: { matchId: 13, slot: 'songAId' },
  10: { matchId: 13, slot: 'songBId' },
  11: { matchId: 14, slot: 'songAId' },
  12: { matchId: 14, slot: 'songBId' },
  13: { matchId: 15, slot: 'songAId' },
  14: { matchId: 15, slot: 'songBId' }
};

export function normalizeModoItalianoBracketStartRound(startRound: unknown): ModoItalianoBracketStartRound {
  return startRound === 'quarterfinals' ? 'quarterfinals' : 'roundOf16';
}

export function getModoItalianoBracketOpeningMatchIds(startRound: unknown): number[] {
  return normalizeModoItalianoBracketStartRound(startRound) === 'quarterfinals' ? QUARTERFINAL_OPENING_MATCH_IDS : ROUND_OF_16_OPENING_MATCH_IDS;
}

export function createDefaultModoItalianoBracketMatches(): ModoItalianoBracketMatch[] {
  return Array.from({ length: MATCH_COUNT }, (_, index) => ({
    id: index + 1,
    songAId: null,
    songBId: null,
    winnerId: null
  }));
}

export function normalizeModoItalianoBracketSongPoolIds(songIds: unknown, songCatalogIds?: Set<number>): number[] {
  if (!Array.isArray(songIds)) {
    return [];
  }

  const normalized = new Set<number>();
  songIds.forEach((songId) => {
    const numericId = typeof songId === 'number' ? songId : typeof songId === 'string' ? Number(songId) : NaN;
    if (!Number.isInteger(numericId) || numericId <= 0) {
      return;
    }
    if (songCatalogIds && !songCatalogIds.has(numericId)) {
      return;
    }
    normalized.add(numericId);
  });

  return Array.from(normalized);
}

export function normalizeModoItalianoBracketDrawSeed(seed: unknown): number {
  const numericSeed = typeof seed === 'number' ? seed : typeof seed === 'string' ? Number(seed) : NaN;
  return Number.isFinite(numericSeed) && numericSeed > 0 ? Math.floor(numericSeed) : 5;
}

export function normalizeModoItalianoBracketDrawDurationSeconds(durationSeconds: unknown, fallbackSeconds = 5): number {
  const numericDuration = typeof durationSeconds === 'number' ? durationSeconds : typeof durationSeconds === 'string' ? Number(durationSeconds) : NaN;
  const fallback = normalizeModoItalianoBracketDrawSeed(fallbackSeconds);
  return Number.isFinite(numericDuration) && numericDuration > 0 ? Math.max(1, Math.floor(numericDuration)) : fallback;
}

export function normalizeModoItalianoBracketDrawCommand(drawCommand: unknown): ModoItalianoBracketDrawCommand | null {
  if (!drawCommand || typeof drawCommand !== 'object' || Array.isArray(drawCommand)) {
    return null;
  }

  const record = drawCommand as Partial<ModoItalianoBracketDrawCommand>;
  if (typeof record.id !== 'number' || typeof record.startedAt !== 'number') {
    return null;
  }

  return {
    id: record.id,
    seed: normalizeModoItalianoBracketDrawSeed(record.seed),
    startedAt: record.startedAt,
    durationSeconds: normalizeModoItalianoBracketDrawDurationSeconds(record.durationSeconds, record.seed),
    songIds: normalizeModoItalianoBracketSongPoolIds(record.songIds),
    selectedSongId: normalizeModoItalianoBracketSongPoolIds([record.selectedSongId])[0] ?? null
  };
}

function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state += 0x6d2b79f5;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function seededShuffle(songIds: number[], seed: number): number[] {
  const shuffled = [...songIds];
  const random = seededRandom(seed);
  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(random() * (index + 1));
    [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
  }
  return shuffled;
}

export function drawModoItalianoBracketOpeningSongs(
  matches: ModoItalianoBracketMatch[],
  startRound: unknown,
  songPoolIds: unknown,
  seed: unknown
): ModoItalianoBracketDrawResult {
  const normalizedStartRound = normalizeModoItalianoBracketStartRound(startRound);
  const nextMatches = normalizeModoItalianoBracketMatches(matches, normalizedStartRound);
  const openingMatchIds = getModoItalianoBracketOpeningMatchIds(normalizedStartRound);
  const slots = openingMatchIds.flatMap((matchId) => [
    { matchId, field: 'songAId' as const },
    { matchId, field: 'songBId' as const }
  ]);
  const usedSongIds = new Set<number>();

  slots.forEach(({ matchId, field }) => {
    const songId = nextMatches[matchId - 1]?.[field];
    if (songId !== null && songId !== undefined) {
      usedSongIds.add(songId);
    }
  });

  const emptySlots = slots.filter(({ matchId, field }) => nextMatches[matchId - 1]?.[field] === null);
  const availableSongIds = seededShuffle(normalizeModoItalianoBracketSongPoolIds(songPoolIds), normalizeModoItalianoBracketDrawSeed(seed)).filter(
    (songId) => !usedSongIds.has(songId)
  );
  const drawnSongIds = availableSongIds.slice(0, emptySlots.length > 0 ? 1 : 0);

  drawnSongIds.forEach((songId, index) => {
    const slot = emptySlots[index];
    if (!slot) {
      return;
    }
    nextMatches[slot.matchId - 1] = {
      ...nextMatches[slot.matchId - 1],
      [slot.field]: songId
    };
  });

  return {
    matches: applyModoItalianoBracketAdvancement(nextMatches, normalizedStartRound),
    drawnSongIds,
    availableSongIds,
    emptySlotCount: emptySlots.length,
    availableSongCount: availableSongIds.length
  };
}

export function fillNextModoItalianoBracketOpeningSlot(
  matches: ModoItalianoBracketMatch[],
  startRound: unknown,
  songId: unknown
): ModoItalianoBracketMatch[] {
  const selectedSongId = normalizeModoItalianoBracketSongPoolIds([songId])[0] ?? null;
  const normalizedStartRound = normalizeModoItalianoBracketStartRound(startRound);
  const nextMatches = normalizeModoItalianoBracketMatches(matches, normalizedStartRound);
  if (selectedSongId === null) {
    return nextMatches;
  }

  const openingMatchIds = getModoItalianoBracketOpeningMatchIds(normalizedStartRound);
  const slots = openingMatchIds.flatMap((matchId) => [
    { matchId, field: 'songAId' as const },
    { matchId, field: 'songBId' as const }
  ]);
  const usedSongIds = new Set<number>();

  slots.forEach(({ matchId, field }) => {
    const currentSongId = nextMatches[matchId - 1]?.[field];
    if (currentSongId !== null && currentSongId !== undefined) {
      usedSongIds.add(currentSongId);
    }
  });

  if (usedSongIds.has(selectedSongId)) {
    return nextMatches;
  }

  const firstEmptySlot = slots.find(({ matchId, field }) => nextMatches[matchId - 1]?.[field] === null);
  if (!firstEmptySlot) {
    return nextMatches;
  }

  nextMatches[firstEmptySlot.matchId - 1] = {
    ...nextMatches[firstEmptySlot.matchId - 1],
    [firstEmptySlot.field]: selectedSongId
  };

  return applyModoItalianoBracketAdvancement(nextMatches, normalizedStartRound);
}

export function normalizeModoItalianoBracketMatches(matches: unknown, startRound: unknown = 'roundOf16'): ModoItalianoBracketMatch[] {
  const safeMatches = createDefaultModoItalianoBracketMatches();

  if (!Array.isArray(matches)) {
    return applyModoItalianoBracketAdvancement(safeMatches, startRound);
  }

  matches.forEach((match) => {
    if (!match || typeof match !== 'object') {
      return;
    }

    const record = match as Partial<ModoItalianoBracketMatch>;
    if (typeof record.id !== 'number' || record.id < 1 || record.id > MATCH_COUNT) {
      return;
    }

    safeMatches[record.id - 1] = {
      ...safeMatches[record.id - 1],
      ...record,
      songAId: typeof record.songAId === 'number' ? record.songAId : null,
      songBId: typeof record.songBId === 'number' ? record.songBId : null,
      winnerId: typeof record.winnerId === 'number' ? record.winnerId : null
    };
  });

  return applyModoItalianoBracketAdvancement(safeMatches, startRound);
}

export function applyModoItalianoBracketAdvancement(matches: ModoItalianoBracketMatch[], startRound: unknown = 'roundOf16'): ModoItalianoBracketMatch[] {
  const nextMatches = matches.map((match) => ({ ...match }));
  const usedOpeningSongs = new Set<number>();
  const openingMatchIds = getModoItalianoBracketOpeningMatchIds(startRound);
  const openingMatchIdSet = new Set(openingMatchIds);
  const firstActiveMatchId = Math.min(...openingMatchIds);
  const firstGeneratedMatchId = Math.max(...openingMatchIds) + 1;

  nextMatches.forEach((match) => {
    if (match.id >= firstGeneratedMatchId) {
      match.songAId = null;
      match.songBId = null;
    }
  });

  nextMatches.forEach((match) => {
    if (!openingMatchIdSet.has(match.id)) {
      return;
    }

    if (match.songAId !== null && usedOpeningSongs.has(match.songAId)) {
      match.songAId = null;
    }
    if (match.songAId !== null) {
      usedOpeningSongs.add(match.songAId);
    }

    if (match.songBId !== null && usedOpeningSongs.has(match.songBId)) {
      match.songBId = null;
    }
    if (match.songBId !== null) {
      usedOpeningSongs.add(match.songBId);
    }
  });

  nextMatches.forEach((match) => {
    if (match.id < firstActiveMatchId) {
      return;
    }

    if (match.winnerId !== null && match.winnerId !== match.songAId && match.winnerId !== match.songBId) {
      match.winnerId = null;
    }

    const target = ADVANCEMENT_TARGETS[match.id];
    if (target) {
      nextMatches[target.matchId - 1][target.slot] = match.winnerId;
    }
  });

  return nextMatches;
}

export type ProgramSequenceMode = 'manual' | 'autoplay' | 'shuffle';
export type ProgramTextContentMode = 'text' | 'sequence';
export type ProgramSongContentMode = 'sequence';

interface BaseSequenceItem {
  id: string;
}

interface BaseSequence<TItem extends BaseSequenceItem> {
  mode: ProgramSequenceMode;
  items: TItem[];
  activeItemId?: string | null;
  intervalMs?: number;
  loop?: boolean;
  startedAt?: number;
}

type RecordValue = Record<string, unknown>;
const MAX_DEPTH = 8;

export interface ProgramTextSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  text: string;
  useMarquee?: boolean;
}

export interface ProgramTextSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramTextSequence;
}

export type ProgramTextSequenceItem =
  | ProgramTextSequenceLeafItem
  | ProgramTextSequenceNestedItem;

export type ProgramTextSequence = BaseSequence<ProgramTextSequenceItem>;

export interface ProgramResolvedTextContent {
  text: string;
  useMarquee: boolean;
  source: ProgramTextContentMode;
  activePathLabels: string[];
}

export interface ProgramResolvedTextLeaf {
  text: string;
  useMarquee: boolean;
  activePathLabels: string[];
}

export interface ProgramSongSequenceLeafItem extends BaseSequenceItem {
  kind: 'preset';
  songId?: number;
  highRotation?: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

export interface ProgramSongSequenceNestedItem extends BaseSequenceItem {
  label: string;
  kind: 'sequence';
  sequence: ProgramSongSequence;
}

export type ProgramSongSequenceItem =
  | ProgramSongSequenceLeafItem
  | ProgramSongSequenceNestedItem;

export type ProgramSongSequence = BaseSequence<ProgramSongSequenceItem>;

export function shuffleProgramSongSequence(
  sequence: ProgramSongSequence,
  activeItemId: string | null = sequence.activeItemId ?? null,
  random: () => number = Math.random
): ProgramSongSequence {
  if (sequence.items.length < 2) return sequence;

  const anchoredItem = activeItemId
    ? sequence.items.find((item) => item.id === activeItemId) ?? null
    : null;
  const shuffledItems = anchoredItem
    ? sequence.items.filter((item) => item.id !== anchoredItem.id)
    : [...sequence.items];

  for (let index = shuffledItems.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.min(index, Math.max(0, Math.floor(random() * (index + 1))));
    [shuffledItems[index], shuffledItems[swapIndex]] = [shuffledItems[swapIndex], shuffledItems[index]];
  }

  const nextItems = anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems;
  if (!nextItems.some((item, index) => item.id !== sequence.items[index]?.id) && shuffledItems.length > 1) {
    shuffledItems.push(shuffledItems.shift()!);
  }

  return {
    ...sequence,
    mode: 'shuffle',
    items: anchoredItem ? [anchoredItem, ...shuffledItems] : shuffledItems,
    activeItemId: anchoredItem?.id ?? sequence.activeItemId ?? nextItems[0]?.id ?? null
  };
}

export interface ProgramResolvedSongLeaf {
  id: string;
  songId?: number;
  highRotation: boolean;
  artist: string;
  title: string;
  coverUrl: string;
  audioUrl?: string;
  durationMs?: number;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
  activePathLabels: string[];
}

function asRecord(value: unknown): RecordValue | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }
  return value as RecordValue;
}

function createId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeMode(value: unknown): ProgramSequenceMode {
  if (value === 'autoplay') return 'autoplay';
  if (value === 'shuffle') return 'shuffle';
  return 'manual';
}

function normalizeTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  if (contentMode === 'text') {
    return 'text';
  }
  if (contentMode === 'sequence') {
    return 'sequence';
  }
  return sequence ? 'sequence' : 'text';
}

function normalizeSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return 'sequence';
}

function normalizeTextLeafItem(
  record: RecordValue,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceLeafItem {
  const text =
    typeof record.text === 'string' && record.text.trim()
      ? record.text
      : typeof record.label === 'string'
        ? record.label
        : '';

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('preset'),
    kind: 'preset',
    text,
    useMarquee: options?.includeMarquee ? Boolean(record.useMarquee) : undefined
  };
}

function normalizeSongLeafItem(record: RecordValue): ProgramSongSequenceLeafItem {
  const artist =
    typeof record.artist === 'string' && record.artist.trim()
      ? record.artist.trim()
      : '';
  const title =
    typeof record.title === 'string' && record.title.trim()
      ? record.title.trim()
      : '';
  const coverUrl =
    typeof record.coverUrl === 'string' && record.coverUrl.trim()
      ? record.coverUrl.trim()
      : '';
  const audioUrl =
    typeof record.audioUrl === 'string' && record.audioUrl.trim()
      ? record.audioUrl.trim()
      : '';
  const durationMs =
    typeof record.durationMs === 'number' &&
    Number.isFinite(record.durationMs) &&
    record.durationMs > 0
      ? Math.round(record.durationMs)
      : undefined;

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('song'),
    kind: 'preset',
    songId:
      typeof record.songId === 'number' && Number.isInteger(record.songId) && record.songId > 0
        ? record.songId
        : undefined,
    highRotation: record.highRotation === true,
    artist,
    title,
    coverUrl,
    audioUrl: audioUrl || undefined,
    durationMs,
    earoneSongId:
      typeof record.earoneSongId === 'string' && record.earoneSongId.trim()
        ? record.earoneSongId.trim()
        : typeof record.earoneSongId === 'number' && Number.isFinite(record.earoneSongId)
          ? String(record.earoneSongId)
          : undefined,
    earoneRank:
      typeof record.earoneRank === 'string' && record.earoneRank.trim()
        ? record.earoneRank.trim()
        : undefined,
    earoneSpins:
      typeof record.earoneSpins === 'string' && record.earoneSpins.trim()
        ? record.earoneSpins.trim()
        : typeof record.earoneSpins === 'number' && Number.isFinite(record.earoneSpins)
          ? String(record.earoneSpins)
          : undefined
  };
}

function withNormalizedSequenceShape<TItem extends BaseSequenceItem>(
  record: RecordValue,
  items: TItem[],
  defaultMode: ProgramSequenceMode = 'manual'
): BaseSequence<TItem> {
  const activeItemId =
    record.activeItemId === null
      ? null
      : typeof record.activeItemId === 'string' && items.some((item) => item.id === record.activeItemId)
      ? record.activeItemId
      : items[0]?.id ?? null;

  return {
    mode: record.mode === undefined ? defaultMode : normalizeMode(record.mode),
    items,
    activeItemId,
    intervalMs:
      typeof record.intervalMs === 'number' && Number.isFinite(record.intervalMs) && record.intervalMs >= 500
        ? Math.floor(record.intervalMs)
        : 4000,
    loop: record.loop === undefined ? true : Boolean(record.loop),
    startedAt:
      typeof record.startedAt === 'number' && Number.isFinite(record.startedAt)
        ? record.startedAt
        : Date.now()
  };
}

function normalizeTextSequenceItem(
  value: unknown,
  depth: number,
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramTextSequence(record.sequence, depth + 1, options);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeTextLeafItem(record, options);
}

function normalizeSongSequenceItem(
  value: unknown,
  depth: number
): ProgramSongSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeProgramSongSequence(record.sequence, depth + 1);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeSongLeafItem(record);
}

function getBaseIndex<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>
): number | null {
  if (sequence.activeItemId === null) {
    return null;
  }

  const activeIndex = sequence.items.findIndex((item) => item.id === sequence.activeItemId);
  return activeIndex >= 0 ? activeIndex : 0;
}

function getSelectedItem<TItem extends BaseSequenceItem>(
  sequence: BaseSequence<TItem>,
  nowMs: number
): TItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const intervalMs = Math.max(500, sequence.intervalMs ?? 4000);
  const elapsedSteps = Math.max(0, Math.floor((nowMs - startedAt) / intervalMs));
  let nextIndex = baseIndex + elapsedSteps;

  if (sequence.loop !== false) {
    nextIndex %= sequence.items.length;
  } else if (nextIndex >= sequence.items.length) {
    nextIndex = sequence.items.length - 1;
  }

  return sequence.items[nextIndex] ?? null;
}

function getSongItemPlaybackDurationMs(
  item: ProgramSongSequenceItem
): number | null {
  if (
    item.kind === 'preset' &&
    typeof item.durationMs === 'number' &&
    Number.isFinite(item.durationMs) &&
    item.durationMs > 0
  ) {
    return Math.max(1, Math.round(item.durationMs));
  }

  return null;
}

function getSelectedSongItem(
  sequence: ProgramSongSequence,
  nowMs: number
): ProgramSongSequenceItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (baseIndex === null) {
    return null;
  }

  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const elapsedMs = Math.max(0, nowMs - startedAt);
  const itemDurations = sequence.items.map((item) => getSongItemPlaybackDurationMs(item));

  if (sequence.loop !== false) {
    const hasUnknownDuration = itemDurations.some((durationMs) => durationMs === null);
    if (!hasUnknownDuration) {
      const cycleDurationMs = itemDurations.reduce<number>((sum, durationMs) => sum + (durationMs ?? 0), 0);
      if (cycleDurationMs <= 0) {
        return sequence.items[baseIndex] ?? null;
      }

      let remainingMs = elapsedMs % cycleDurationMs;
      for (let step = 0; step < sequence.items.length; step += 1) {
        const index = (baseIndex + step) % sequence.items.length;
        const itemDurationMs = itemDurations[index];
        if (typeof itemDurationMs !== 'number') {
          return sequence.items[index] ?? null;
        }
        if (remainingMs < itemDurationMs) {
          return sequence.items[index] ?? null;
        }
        remainingMs -= itemDurationMs;
      }

      return sequence.items[baseIndex] ?? null;
    }

    let remainingMs = elapsedMs;
    for (let step = 0; step < sequence.items.length; step += 1) {
      const index = (baseIndex + step) % sequence.items.length;
      const itemDurationMs = itemDurations[index];
      if (typeof itemDurationMs !== 'number') {
        return sequence.items[index] ?? null;
      }
      if (remainingMs < itemDurationMs) {
        return sequence.items[index] ?? null;
      }
      remainingMs -= itemDurationMs;
    }

    return sequence.items[baseIndex] ?? null;
  }

  let index = baseIndex;
  let remainingMs = elapsedMs;
  while (index < sequence.items.length - 1) {
    const itemDurationMs = itemDurations[index];
    if (typeof itemDurationMs !== 'number') {
      return sequence.items[index] ?? null;
    }
    if (remainingMs < itemDurationMs) {
      break;
    }
    remainingMs -= itemDurationMs;
    index += 1;
  }

  return sequence.items[index] ?? null;
}

function resolveTextSequenceRecursive(
  sequence: ProgramTextSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedTextLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveTextSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  return {
    text: selected.text,
    useMarquee: Boolean(selected.useMarquee),
    activePathLabels: [...labels, selected.text]
  };
}

function resolveSongSequenceRecursive(
  sequence: ProgramSongSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ProgramResolvedSongLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedSongItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveSongSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  const songLabel = [selected.artist, selected.title].filter(Boolean).join(' - ');
  return {
    id: selected.id,
    songId: selected.songId,
    highRotation: selected.highRotation === true,
    artist: selected.artist,
    title: selected.title,
    coverUrl: selected.coverUrl,
    audioUrl: selected.audioUrl,
    durationMs: selected.durationMs,
    earoneSongId: selected.earoneSongId,
    earoneRank: selected.earoneRank,
    earoneSpins: selected.earoneSpins,
    activePathLabels: [...labels, songLabel || 'Song Preset']
  };
}

export function normalizeProgramTextSequence(
  value: unknown,
  depth = 0,
  options?: { includeMarquee?: boolean }
): ProgramTextSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeTextSequenceItem(item, depth, options))
    .filter((item): item is ProgramTextSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items);
}

export function normalizeProgramSongSequence(
  value: unknown,
  depth = 0
): ProgramSongSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeSongSequenceItem(item, depth))
    .filter((item): item is ProgramSongSequenceItem => item !== null);

  return withNormalizedSequenceShape(record, items, 'autoplay');
}

export function createProgramTextSequenceItem(
  kind: ProgramTextSequenceItem['kind'] = 'preset',
  options?: { includeMarquee?: boolean }
): ProgramTextSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramTextSequence('manual', options)
    };
  }

  return {
    id: createId('preset'),
    kind: 'preset',
    text: '',
    useMarquee: options?.includeMarquee ? false : undefined
  };
}

export function createProgramSongSequenceItem(
  kind: ProgramSongSequenceItem['kind'] = 'preset'
): ProgramSongSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createProgramSongSequence('manual')
    };
  }

  return {
    id: createId('song'),
    kind: 'preset',
    highRotation: false,
    artist: '',
    title: '',
    coverUrl: '',
    audioUrl: '',
    durationMs: undefined
  };
}

export function createProgramTextSequence(
  mode: ProgramSequenceMode = 'manual',
  options?: { includeMarquee?: boolean }
): ProgramTextSequence {
  const firstItem = createProgramTextSequenceItem('preset', options);

  return {
    mode,
    items: [firstItem],
    activeItemId: firstItem.id,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function createProgramSongSequence(
  mode: ProgramSequenceMode = 'autoplay'
): ProgramSongSequence {
  return {
    mode,
    items: [],
    activeItemId: null,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

export function getProgramTextContentMode(
  contentMode: unknown,
  sequence: ProgramTextSequence | null
): ProgramTextContentMode {
  return normalizeTextContentMode(contentMode, sequence);
}

export function getProgramSongContentMode(
  contentMode: unknown,
  sequence: ProgramSongSequence | null
): ProgramSongContentMode {
  return normalizeSongContentMode(contentMode, sequence);
}

export function getProgramTextSequenceSelectedItemId(
  sequence: ProgramTextSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedItem(sequence, nowMs)?.id ?? null;
}

export function getProgramSongSequenceSelectedItemId(
  sequence: ProgramSongSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedSongItem(sequence, nowMs)?.id ?? null;
}

export function resolveProgramTextContent(
  config: {
    text?: string;
    useMarquee?: boolean;
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextContent {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode === 'sequence' && normalizedSequence) {
    const resolved = resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
    if (resolved) {
      return {
        text: resolved.text,
        useMarquee: resolved.useMarquee,
        source: 'sequence',
        activePathLabels: resolved.activePathLabels
      };
    }
  }

  return {
    text: typeof config.text === 'string' ? config.text : '',
    useMarquee: Boolean(config.useMarquee),
    source: 'text',
    activePathLabels: []
  };
}

export function resolveProgramTextLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now(),
  options?: { includeMarquee?: boolean }
): ProgramResolvedTextLeaf | null {
  const normalizedSequence = normalizeProgramTextSequence(config.sequence, 0, options);
  const contentMode = normalizeTextContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveTextSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function resolveProgramSongLeaf(
  config: {
    contentMode?: unknown;
    sequence?: unknown;
  },
  nowMs = Date.now()
): ProgramResolvedSongLeaf | null {
  const normalizedSequence = normalizeProgramSongSequence(config.sequence);
  const contentMode = normalizeSongContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveSongSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function countProgramTextSequenceLeafItems(
  sequence: ProgramTextSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramTextSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

export function countProgramSongSequenceLeafItems(
  sequence: ProgramSongSequence | null
): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countProgramSongSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

