export function isEditableTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable) return true;
  const tagName = target.tagName;
  return tagName === 'INPUT' || tagName === 'TEXTAREA' || tagName === 'SELECT';
}

export function getInstantShortcutLetter(index: number): string | null {
  if (index < 0 || index >= INSTANT_SHORTCUT_KEYS.length) return null;
  return INSTANT_SHORTCUT_KEYS[index].toUpperCase();
}

export function normalizeMasterVolume(value: unknown, fallback: number = 1): number {
  if (typeof value === 'number' && Number.isFinite(value)) return Math.max(0, Math.min(1, value));
  return fallback;
}

export function normalizeTakeVolumePresetDb(value: unknown, fallback: number): number {
  const numeric = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.max(TAKE_VOLUME_PRESET_MIN_DB, Math.min(TAKE_VOLUME_PRESET_MAX_DB, numeric));
}

export function normalizeTakeVolumeFadeMs(value: unknown, fallback: number): number {
  const numeric = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.max(0, Math.min(20000, Math.round(numeric)));
}

export function normalizeMixerToggle(value: unknown, fallback: boolean = false): boolean {
  return typeof value === 'boolean' ? value : fallback;
}

export function defaultMixerChannelsFromScalars(source: {
  songMasterVolume: number; instantMasterVolume: number;
  sceneInstantMasterVolume: number; streamMasterVolume: number;
  songMuted: boolean; instantMuted: boolean;
  sceneInstantMuted: boolean; streamMuted: boolean;
  songSolo: boolean; instantSolo: boolean;
  sceneInstantSolo: boolean; streamSolo: boolean;
}): MixerChannelSetting[] {
  return [
    { id: 'song', name: 'Song', volume: source.songMasterVolume, muted: source.songMuted, solo: source.songSolo },
    { id: 'stream', name: 'Stream', volume: source.streamMasterVolume, muted: source.streamMuted, solo: source.streamSolo },
    { id: 'instants', name: 'Instants', volume: source.instantMasterVolume, muted: source.instantMuted, solo: source.instantSolo },
    { id: 'sceneInstant', name: 'Scene Instant', volume: source.sceneInstantMasterVolume, muted: source.sceneInstantMuted, solo: source.sceneInstantSolo }
  ];
}

export function normalizeMixerChannelsPayload(value: unknown, fallbackChannels: MixerChannelSetting[]): MixerChannelSetting[] {
  if (!Array.isArray(value)) return fallbackChannels;
  const byId = new Map<string, MixerChannelSetting>();
  for (const fc of fallbackChannels) byId.set(fc.id, { ...fc });
  for (const item of value) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const record = item as Record<string, unknown>;
    const id = typeof record.id === 'string' ? record.id.trim() : '';
    if (!id) continue;
    const prev = byId.get(id);
    const name = typeof record.name === 'string' && record.name.trim() ? record.name.trim() : (prev?.name ?? id);
    byId.set(id, {
      id, name,
      volume: normalizeMasterVolume(record.volume, prev?.volume ?? 1),
      muted: normalizeMixerToggle(record.muted, prev?.muted ?? false),
      solo: normalizeMixerToggle(record.solo, prev?.solo ?? false)
    });
  }
  return [...byId.values()];
}

export function getMixerChannelById(channels: MixerChannelSetting[], channelId: string): MixerChannelSetting {
  return channels.find(c => c.id === channelId) ?? { id: channelId, name: channelId, volume: 1, muted: false, solo: false };
}

export function normalizeBroadcastSettingsPayload(value: unknown): BroadcastSettings {
  const record = value && typeof value === 'object' ? (value as Record<string, unknown>) : {};
  const scalarFallback = {
    songMasterVolume: normalizeMasterVolume(record.songMasterVolume, 1),
    instantMasterVolume: normalizeMasterVolume(record.instantMasterVolume, 1),
    sceneInstantMasterVolume: normalizeMasterVolume(record.sceneInstantMasterVolume, 1),
    streamMasterVolume: normalizeMasterVolume(record.streamMasterVolume, 1),
    songMuted: normalizeMixerToggle(record.songMuted, false),
    instantMuted: normalizeMixerToggle(record.instantMuted, false),
    sceneInstantMuted: normalizeMixerToggle(record.sceneInstantMuted, false),
    streamMuted: normalizeMixerToggle(record.streamMuted, false),
    songSolo: normalizeMixerToggle(record.songSolo, false),
    instantSolo: normalizeMixerToggle(record.instantSolo, false),
    sceneInstantSolo: normalizeMixerToggle(record.sceneInstantSolo, false),
    streamSolo: normalizeMixerToggle(record.streamSolo, false)
  };
  const mixerChannels = normalizeMixerChannelsPayload(record.mixerChannels, defaultMixerChannelsFromScalars(scalarFallback));
  const songChannel = getMixerChannelById(mixerChannels, 'song');
  const streamChannel = getMixerChannelById(mixerChannels, 'stream');
  const instantsChannel = getMixerChannelById(mixerChannels, 'instants');
  const sceneInstantChannel = getMixerChannelById(mixerChannels, 'sceneInstant');
  return {
    mainMasterVolume: normalizeMasterVolume(record.mainMasterVolume, 1),
    songMasterVolume: songChannel.volume,
    instantMasterVolume: instantsChannel.volume,
    sceneInstantMasterVolume: sceneInstantChannel.volume,
    streamMasterVolume: streamChannel.volume,
    songMuted: songChannel.muted,
    instantMuted: instantsChannel.muted,
    sceneInstantMuted: sceneInstantChannel.muted,
    streamMuted: streamChannel.muted,
    songSolo: songChannel.solo,
    instantSolo: instantsChannel.solo,
    sceneInstantSolo: sceneInstantChannel.solo,
    streamSolo: streamChannel.solo,
    mixerChannels
  };
}

export function withNormalizedMixerChannels(value: BroadcastSettings): BroadcastSettings {
  const existing = normalizeMixerChannelsPayload(value.mixerChannels, defaultMixerChannelsFromScalars(value));
  const byId = new Map(existing.map(c => [c.id, c] as const));
  for (const nc of defaultMixerChannelsFromScalars(value)) byId.set(nc.id, nc);
  return { ...value, mixerChannels: [...byId.values()] };
}

export function normalizeAudioMeterLevel(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0;
}

export function createEmptyMeterChannel() {
  return { vu: 0, peak: 0, peakHold: 0 };
}

export function normalizeProgramMeterChannel(value: unknown): { vu: number; peak: number; peakHold: number } {
  if (typeof value === 'number' && Number.isFinite(value)) {
    const n = normalizeAudioMeterLevel(value);
    return { vu: n, peak: n, peakHold: n };
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) return createEmptyMeterChannel();
  const r = value as Record<string, unknown>;
  const vu = normalizeAudioMeterLevel(r.vu ?? r.level);
  const peak = Math.max(vu, normalizeAudioMeterLevel(r.peak ?? vu));
  const peakHold = Math.max(peak, normalizeAudioMeterLevel(r.peakHold ?? peak));
  return { vu, peak, peakHold };
}

export function normalizeProgramAudioMeter(value: unknown): ProgramAudioMeterLevels {
  if (!value || typeof value !== 'object') {
    return { song: createEmptyMeterChannel(), instants: createEmptyMeterChannel(), sceneInstant: createEmptyMeterChannel(), main: createEmptyMeterChannel(), updatedAt: new Date(0).toISOString() };
  }
  const r = value as Record<string, unknown>;
  return {
    song: normalizeProgramMeterChannel(r.song),
    instants: normalizeProgramMeterChannel(r.instants),
    sceneInstant: normalizeProgramMeterChannel(r.sceneInstant),
    main: normalizeProgramMeterChannel(r.main),
    updatedAt: typeof r.updatedAt === 'string' ? r.updatedAt : new Date().toISOString()
  };
}

export function normalizeProgramSongPlayback(value: unknown): ProgramSongPlaybackState {
  if (!value || typeof value !== 'object') {
    return { token: '', audioUrl: '', progress: 0, currentTimeMs: 0, durationMs: null, isPlaying: false, updatedAt: new Date(0).toISOString() };
  }
  const r = value as Record<string, unknown>;
  const durationMs = typeof r.durationMs === 'number' && Number.isFinite(r.durationMs) && r.durationMs > 0 ? Math.round(r.durationMs) : null;
  let currentTimeMs = typeof r.currentTimeMs === 'number' && Number.isFinite(r.currentTimeMs) ? Math.max(0, Math.round(r.currentTimeMs)) : 0;
  if (durationMs !== null) currentTimeMs = Math.min(currentTimeMs, durationMs);
  return {
    token: typeof r.token === 'string' ? r.token : '',
    audioUrl: typeof r.audioUrl === 'string' ? r.audioUrl : '',
    title: typeof r.title === 'string' ? r.title : undefined,
    artist: typeof r.artist === 'string' ? r.artist : undefined,
    coverUrl: typeof r.coverUrl === 'string' ? r.coverUrl : undefined,
    progress: normalizeAudioMeterLevel(r.progress),
    currentTimeMs, durationMs,
    isPlaying: Boolean(r.isPlaying),
    startedAt: typeof r.startedAt === 'string' ? r.startedAt : undefined,
    updatedAt: typeof r.updatedAt === 'string' ? r.updatedAt : new Date().toISOString(),
    telemetryStale: typeof r.telemetryStale === 'boolean' ? r.telemetryStale : undefined,
    introStatus: r.introStatus === 'pending' || r.introStatus === 'playing' || r.introStatus === 'completed' || r.introStatus === 'degraded' ? r.introStatus : 'none',
    introFailureReason: typeof r.introFailureReason === 'string' ? r.introFailureReason.trim().slice(0, 200) || null : null,
    queueEntryId: typeof r.queueEntryId === 'string' && r.queueEntryId.trim() ? r.queueEntryId.trim() : null
  };
}

export function normalizeSceneInstantPlayback(value: unknown): SceneInstantPlaybackState {
  if (!value || typeof value !== 'object') {
    return { sceneId: null, instantId: null, mediaAssetId: null, instantName: '', isPlaying: false, updatedAt: new Date(0).toISOString() };
  }
  const r = value as Record<string, unknown>;
  const instant = r.instant && typeof r.instant === 'object' && !Array.isArray(r.instant) ? (r.instant as Record<string, unknown>) : null;
  return {
    sceneId: normalizeSceneInstantId(r.sceneId),
    instantId: normalizeSceneInstantId(r.instantId ?? instant?.id),
    mediaAssetId:
      typeof (r.mediaAssetId ?? instant?.assetId) === 'string' && String(r.mediaAssetId ?? instant?.assetId).trim()
        ? String(r.mediaAssetId ?? instant?.assetId).trim()
        : null,
    instantName: typeof instant?.name === 'string' ? instant.name : '',
    isPlaying: Boolean(r.isPlaying),
    updatedAt: typeof r.updatedAt === 'string' ? r.updatedAt : new Date().toISOString()
  };
}

export function normalizeUpdateVersion(value: unknown): number | null {
  const numeric = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(numeric)) return null;
  const normalized = Math.floor(numeric);
  return normalized < 0 ? null : normalized;
}

export function resolveControlUpdateTopicFromType(type: unknown): ProgramUpdateTopic | null {
  if (typeof type !== 'string') return null;
  switch (type) {
    case 'program_state_snapshot': case 'scene_change': case 'scene_staged': case 'fade_to_black': case 'scene_update': case 'scene_cleared': case 'program_scenes_changed': case 'program_media_groups_changed': return 'state';
    case 'audio_bus_snapshot': case 'audio_bus_update': case 'song_queue_update': return 'audioBus';
    case 'audio_meter_update': return 'audioMeter';
    case 'song_playback_update': case 'song_off_air': return 'songPlayback';
    case 'scene_instant_state': case 'scene_instant_take': case 'scene_instant_stop': return 'sceneInstant';
    case 'flight_update': return 'flight';
    default: return null;
  }
}

export function readControlUpdateVersion(topic: ProgramUpdateTopic, payload: unknown): number | null {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return null;
  const record = payload as Record<string, unknown>;
  const topLevel = normalizeUpdateVersion(record.version);
  if (topLevel !== null) return topLevel;
  switch (topic) {
    case 'state': return normalizeUpdateVersion((record.state as Record<string, unknown> | undefined)?.version ?? record.stateVersion);
    case 'audioBus': return normalizeUpdateVersion((record.settings as Record<string, unknown> | undefined)?.version ?? record.audioBusVersion);
    case 'audioMeter': return normalizeUpdateVersion((record.levels as Record<string, unknown> | undefined)?.version ?? record.audioMeterVersion);
    case 'songPlayback': return normalizeUpdateVersion((record.playback as Record<string, unknown> | undefined)?.version ?? record.songPlaybackVersion);
    case 'sceneInstant': return normalizeUpdateVersion((record.playback as Record<string, unknown> | undefined)?.version ?? record.sceneInstantVersion);
    case 'flight': return normalizeUpdateVersion(record.flightVersion);
    default: return null;
  }
}

export function reconcileProgramSongPlayback(prev: ProgramSongPlaybackState, next: ProgramSongPlaybackState): ProgramSongPlaybackState {
  if (prev.token && next.token && prev.token === next.token && prev.audioUrl === next.audioUrl && prev.isPlaying) {
    if (prev.currentTimeMs - next.currentTimeMs > SONG_PLAYBACK_MAX_BACKWARD_DRIFT_MS) return prev;
  }
  return next;
}

export function reconcileProgramSongOffAir(
  prev: ProgramSongPlaybackState,
  playback: unknown,
  triggeredAt: unknown,
): ProgramSongPlaybackState {
  if (playback && typeof playback === 'object' && !Array.isArray(playback)) {
    return normalizeProgramSongPlayback(playback);
  }
  return {
    ...prev,
    isPlaying: false,
    updatedAt: typeof triggeredAt === 'string' ? triggeredAt : new Date().toISOString()
  };
}

export function reconcileProgramAudioMeter(prev: ProgramAudioMeterLevels, next: ProgramAudioMeterLevels): ProgramAudioMeterLevels {
  const deltas = [
    Math.abs(prev.song.vu - next.song.vu), Math.abs(prev.song.peak - next.song.peak), Math.abs(prev.song.peakHold - next.song.peakHold),
    Math.abs(prev.instants.vu - next.instants.vu), Math.abs(prev.instants.peak - next.instants.peak), Math.abs(prev.instants.peakHold - next.instants.peakHold),
    Math.abs(prev.sceneInstant.vu - next.sceneInstant.vu), Math.abs(prev.sceneInstant.peak - next.sceneInstant.peak), Math.abs(prev.sceneInstant.peakHold - next.sceneInstant.peakHold),
    Math.abs(prev.main.vu - next.main.vu), Math.abs(prev.main.peak - next.main.peak), Math.abs(prev.main.peakHold - next.main.peakHold)
  ];
  if (deltas.every(d => d < AUDIO_METER_UI_EPSILON)) return prev;
  return next;
}

export function normalizeProgramState(value: unknown): ProgramState | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Partial<ProgramState> & { activeScene?: unknown; stagedScene?: unknown };
  return {
    ...(record as ProgramState),
    scenes: Array.isArray(record.scenes) ? record.scenes : [],
    mediaGroups: Array.isArray(record.mediaGroups) ? record.mediaGroups : [],
    activeSceneId: typeof record.activeSceneId === 'number' ? record.activeSceneId : null,
    stagedSceneId: typeof record.stagedSceneId === 'number' ? record.stagedSceneId : null,
    fadeToBlack: record.fadeToBlack === true,
    activeScene: record.activeScene && typeof record.activeScene === 'object' ? (record.activeScene as Scene) : null,
    stagedScene: record.stagedScene && typeof record.stagedScene === 'object' ? (record.stagedScene as Scene) : null
  };
}

export function meterLevelToFill(value: unknown): number {
  return Math.max(0, Math.min(1, Math.pow(normalizeAudioMeterLevel(value), 0.6)));
}

export function formatMixerLevelInputValue(value: number): string {
  const db = faderToDb(value);
  return Number.isFinite(db) ? db.toFixed(1) : '-inf';
}

export function parseMixerLevelInputToFader(rawValue: string, fallbackValue: number): number {
  const normalized = rawValue.trim().toLowerCase();
  if (!normalized) return fallbackValue;
  if (['-inf', '-infinity', '-∞'].includes(normalized)) return 0;
  const parsedDb = Number.parseFloat(normalized.replace(/db$/i, '').trim());
  return Number.isFinite(parsedDb) ? dbToFader(parsedDb) : fallbackValue;
}

export function normalizeSlideshowImageList(value: unknown): string[] {
  const collected: string[] = [];
  const append = (raw: string) => {
    raw.split(/[\n,]/g).map(e => e.trim()).filter(Boolean).forEach(e => collected.push(e));
  };
  if (Array.isArray(value)) {
    value.forEach(e => { if (typeof e === 'string') append(e); });
  } else if (typeof value === 'string') {
    append(value);
  }
  const seen = new Set<string>();
  return collected.filter(e => { if (seen.has(e)) return false; seen.add(e); return true; });
}

export function normalizeSlideshowMediaGroupId(value: unknown): number | null {
  const numeric = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(numeric) && numeric > 0 && Number.isInteger(numeric) ? numeric : null;
}

export function normalizeSlideshowLabelId(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

export function normalizeSceneInstantId(value: unknown): number | null {
  const numeric = typeof value === 'number' ? value : Number(value);
  return Number.isFinite(numeric) && numeric > 0 && Number.isInteger(numeric) ? numeric : null;
}

export function parseSceneMetadata(metadata: string | null): ComponentPropsMap {
  try {
    const parsed = metadata ? JSON.parse(metadata) : {};
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch {}
  return {};
}

export function withIndependentProgramClockMetadata(metadata: ComponentPropsMap): ComponentPropsMap {
  return metadata;
}

export function formatTakePresetDbInputValue(value: number): string {
  if (!Number.isFinite(value)) return '-15.0';
  return value.toFixed(1);
}

import type { FlightCue, FlightCueKind, FlightMixerChange, FlightSequence } from '../models/broadcast';

const VALID_CUE_KINDS: Set<FlightCueKind> = new Set([
  'scene',
  'playSong',
  'stopSong',
  'wait',
  'waitForSongEnd',
  'sceneUpdate',
  'instant',
  'mixer'
]);

const VALID_MIXER_CHANNEL_IDS: Set<FlightMixerChange['channelId']> = new Set([
  'main',
  'song',
  'instants',
  'sceneInstant',
  'stream'
]);

function createId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function normalizeOptionalString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : undefined;
  }
  return undefined;
}

function normalizeOptionalNumber(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return Math.round(value);
  }
  return undefined;
}

export function normalizeFlightCue(value: unknown): FlightCue | null {
  if (!isRecord(value)) {
    return null;
  }

  const kind = value.kind;
  if (typeof kind !== 'string' || !VALID_CUE_KINDS.has(kind as FlightCueKind)) {
    return null;
  }

  const cue: FlightCue = {
    id: typeof value.id === 'string' && value.id.trim().length > 0 ? value.id.trim() : createId('cue'),
    kind: kind as FlightCueKind,
    label: normalizeOptionalString(value.label)
  };

  if (typeof value.isFiller === 'boolean') cue.isFiller = value.isFiller;
  const clockOffsetSeconds = normalizeOptionalNumber(value.clockOffsetSeconds);
  if (clockOffsetSeconds !== undefined) cue.clockOffsetSeconds = clockOffsetSeconds;
  const voiceTrackInstantId = normalizeOptionalNumber(value.voiceTrackInstantId);
  if (voiceTrackInstantId !== undefined) cue.voiceTrackInstantId = voiceTrackInstantId;
  for (const field of ['voiceDuckGain', 'voiceFadeInSeconds', 'voiceFadeOutSeconds'] as const) {
    if (typeof value[field] === 'number' && Number.isFinite(value[field])) cue[field] = value[field] as number;
  }

  const sceneId = normalizeOptionalNumber(value.sceneId);
  if (sceneId !== undefined) {
    cue.sceneId = sceneId;
  }

  const transitionId = normalizeOptionalString(value.transitionId);
  if (transitionId !== undefined) {
    cue.transitionId = transitionId;
  }

  const songId = normalizeOptionalNumber(value.songId);
  if (songId !== undefined) {
    cue.songId = songId;
  }

  const durationMs = normalizeOptionalNumber(value.durationMs);
  if (durationMs !== undefined && durationMs >= 0) {
    cue.durationMs = durationMs;
  }

  if (isRecord(value.metadataPatch)) {
    cue.metadataPatch = value.metadataPatch as Record<string, unknown>;
  }

  const instantId = normalizeOptionalNumber(value.instantId);
  if (instantId !== undefined) {
    cue.instantId = instantId;
  }

  if (isRecord(value.mixerChange)) {
    const change: FlightMixerChange = {};
    const channelId = value.mixerChange.channelId;
    if (VALID_MIXER_CHANNEL_IDS.has(channelId as FlightMixerChange['channelId'])) {
      change.channelId = channelId as FlightMixerChange['channelId'];
    }
    const volume = normalizeOptionalNumber(value.mixerChange.volume);
    if (volume !== undefined) {
      change.volume = volume;
    }
    if (typeof value.mixerChange.muted === 'boolean') {
      change.muted = value.mixerChange.muted;
    }
    if (typeof value.mixerChange.solo === 'boolean') {
      change.solo = value.mixerChange.solo;
    }
    cue.mixerChange = change;
  }

  return cue;
}

export function normalizeFlightSequence(value: unknown): FlightSequence | null {
  if (!isRecord(value)) {
    return null;
  }

  const rawItems = Array.isArray(value.items) ? value.items : [];
  const items = rawItems
    .map(normalizeFlightCue)
    .filter((cue): cue is FlightCue => cue !== null);

  return {
    id: typeof value.id === 'number' && Number.isFinite(value.id) ? value.id : 0,
    name: typeof value.name === 'string' ? value.name : 'Unnamed',
    items,
    loop: value.loop === true,
    isRunning: value.isRunning === true,
    activeItemId: value.activeItemId === null || typeof value.activeItemId === 'string' ? value.activeItemId : null,
    scheduledAt: typeof value.scheduledAt === 'string' ? value.scheduledAt : null,
    publishedAt: typeof value.publishedAt === 'string' ? value.publishedAt : null,
    lastStartedAt: typeof value.lastStartedAt === 'string' ? value.lastStartedAt : null,
    revision: typeof value.revision === 'number' && Number.isInteger(value.revision) ? value.revision : 1,
    createdAt: typeof value.createdAt === 'string' ? value.createdAt : new Date().toISOString(),
    updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : new Date().toISOString()
  };
}

export function createFlightCue(kind: FlightCueKind = 'wait'): FlightCue {
  const cue: FlightCue = {
    id: createId('cue'),
    kind
  };

  if (kind === 'wait') {
    cue.durationMs = 3000;
  }

  if (kind === 'scene') {
    cue.transitionId = 'cut';
  }

  return cue;
}

export function getFlightCueDisplayLabel(
  cue: FlightCue,
  context?: {
    scenes?: { id: number; name: string }[];
    songs?: { id: number; title: string; artist: string }[];
    instants?: { id: number; name: string }[];
  }
): string {
  if (cue.label) {
    return cue.label;
  }

  switch (cue.kind) {
    case 'scene':
      if (cue.sceneId !== undefined) {
        const scene = context?.scenes?.find((s) => s.id === cue.sceneId);
        return scene ? `Scene: ${scene.name}` : `Scene ${cue.sceneId}`;
      }
      return 'Scene';
    case 'playSong':
      if (cue.songId !== undefined) {
        const song = context?.songs?.find((s) => s.id === cue.songId);
        return song ? `Play: ${song.artist} - ${song.title}` : `Play song ${cue.songId}`;
      }
      return 'Play song';
    case 'stopSong':
      return 'Stop song';
    case 'wait':
      return cue.durationMs !== undefined ? `Wait ${cue.durationMs}ms` : 'Wait';
    case 'waitForSongEnd':
      return 'Wait for song end';
    case 'sceneUpdate':
      return cue.sceneId !== undefined ? `Update scene ${cue.sceneId}` : 'Update scene';
    case 'instant':
      if (cue.instantId !== undefined) {
        const instant = context?.instants?.find((i) => i.id === cue.instantId);
        return instant ? `Instant: ${instant.name}` : `Instant ${cue.instantId}`;
      }
      return 'Instant';
    case 'mixer':
      if (cue.mixerChange?.channelId) {
        const parts: string[] = [cue.mixerChange.channelId];
        if (typeof cue.mixerChange.volume === 'number') parts.push(`vol ${Math.round(cue.mixerChange.volume * 100)}%`);
        if (typeof cue.mixerChange.muted === 'boolean') parts.push(cue.mixerChange.muted ? 'mute' : 'unmute');
        if (typeof cue.mixerChange.solo === 'boolean') parts.push(cue.mixerChange.solo ? 'solo' : 'unsolo');
        return `Mixer: ${parts.join(' ')}`;
      }
      return 'Mixer';
    default:
      return 'Cue';
  }
}

import { readChartSongValues, type ChartSongValues } from './programChartValues';

export type ToniChyronContentMode = 'text' | 'sequence';
export type ToniChyronSequenceMode = 'manual' | 'autoplay';

export interface ToniChyronSequenceLeafItem extends ChartSongValues {
  id: string;
  kind: 'preset';
  text: string;
  useMarquee?: boolean;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
}

export interface ToniChyronSequenceNestedItem {
  id: string;
  label: string;
  kind: 'sequence';
  sequence: ToniChyronSequence;
}

export type ToniChyronSequenceItem =
  | ToniChyronSequenceLeafItem
  | ToniChyronSequenceNestedItem;

export interface ToniChyronSequence {
  mode: ToniChyronSequenceMode;
  items: ToniChyronSequenceItem[];
  activeItemId?: string | null;
  intervalMs?: number;
  loop?: boolean;
  startedAt?: number;
}

export interface ToniChyronResolvedContent {
  text: string;
  useMarquee: boolean;
  source: ToniChyronContentMode;
  activePathLabels: string[];
}

export interface ToniChyronResolvedLeaf extends ChartSongValues {
  text: string;
  useMarquee: boolean;
  earoneSongId?: string;
  earoneRank?: string;
  earoneSpins?: string;
  activePathLabels: string[];
}

type RecordValue = Record<string, unknown>;

const MAX_DEPTH = 8;

function asRecord(value: unknown): RecordValue | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }
  return value as RecordValue;
}

function createId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function normalizeMode(value: unknown): ToniChyronSequenceMode {
  return value === 'autoplay' ? 'autoplay' : 'manual';
}

function normalizeLeafItem(record: RecordValue): ToniChyronSequenceLeafItem {
  const text =
    typeof record.text === 'string' && record.text.trim()
      ? record.text
      : typeof record.label === 'string'
        ? record.label
        : '';

  return {
    id: typeof record.id === 'string' && record.id ? record.id : createId('preset'),
    kind: 'preset',
    text,
    useMarquee: Boolean(record.useMarquee),
    earoneSongId:
      typeof record.earoneSongId === 'string' && record.earoneSongId.trim()
        ? record.earoneSongId.trim()
        : typeof record.earoneSongId === 'number' && Number.isFinite(record.earoneSongId)
          ? String(record.earoneSongId)
          : undefined,
    earoneRank:
      typeof record.earoneRank === 'string' && record.earoneRank.trim()
        ? record.earoneRank.trim()
        : undefined,
    earoneSpins:
      typeof record.earoneSpins === 'string' && record.earoneSpins.trim()
        ? record.earoneSpins.trim()
        : typeof record.earoneSpins === 'number' && Number.isFinite(record.earoneSpins)
          ? String(record.earoneSpins)
          : undefined,
    ...readChartSongValues(record)
  };
}

function normalizeSequenceItem(value: unknown, depth: number): ToniChyronSequenceItem | null {
  const record = asRecord(value);
  if (!record) {
    return null;
  }

  if (record.kind === 'sequence') {
    const normalizedSequence = normalizeToniChyronSequence(record.sequence, depth + 1);
    if (!normalizedSequence) {
      return null;
    }

    return {
      id: typeof record.id === 'string' && record.id ? record.id : createId('sequence'),
      label: typeof record.label === 'string' && record.label.trim() ? record.label : 'Nested Sequence',
      kind: 'sequence',
      sequence: normalizedSequence
    };
  }

  return normalizeLeafItem(record);
}

export function normalizeToniChyronSequence(
  value: unknown,
  depth = 0
): ToniChyronSequence | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const record = asRecord(value);
  if (!record) {
    return null;
  }

  const rawItems = Array.isArray(record.items) ? record.items : [];
  const items = rawItems
    .map((item) => normalizeSequenceItem(item, depth))
    .filter((item): item is ToniChyronSequenceItem => item !== null);

  const activeItemId =
    typeof record.activeItemId === 'string' && items.some((item) => item.id === record.activeItemId)
      ? record.activeItemId
      : items[0]?.id ?? null;

  return {
    mode: normalizeMode(record.mode),
    items,
    activeItemId,
    intervalMs:
      typeof record.intervalMs === 'number' && Number.isFinite(record.intervalMs) && record.intervalMs >= 500
        ? Math.floor(record.intervalMs)
        : 4000,
    loop: record.loop === undefined ? true : Boolean(record.loop),
    startedAt:
      typeof record.startedAt === 'number' && Number.isFinite(record.startedAt)
        ? record.startedAt
        : Date.now()
  };
}

export function createToniChyronSequenceItem(
  kind: ToniChyronSequenceItem['kind'] = 'preset'
): ToniChyronSequenceItem {
  if (kind === 'sequence') {
    return {
      id: createId('sequence'),
      label: 'Nested Sequence',
      kind: 'sequence',
      sequence: createToniChyronSequence('manual')
    };
  }

  return {
    id: createId('preset'),
    kind: 'preset',
    text: '',
    useMarquee: false
  };
}

export function createToniChyronSequence(
  mode: ToniChyronSequenceMode = 'manual'
): ToniChyronSequence {
  const firstItem = createToniChyronSequenceItem('preset');

  return {
    mode,
    items: [firstItem],
    activeItemId: firstItem.id,
    intervalMs: 4000,
    loop: true,
    startedAt: Date.now()
  };
}

function getBaseIndex(sequence: ToniChyronSequence): number {
  const activeIndex = sequence.items.findIndex((item) => item.id === sequence.activeItemId);
  return activeIndex >= 0 ? activeIndex : 0;
}

function getSelectedItem(
  sequence: ToniChyronSequence,
  nowMs: number
): ToniChyronSequenceItem | null {
  if (sequence.items.length === 0) {
    return null;
  }

  const baseIndex = getBaseIndex(sequence);
  if (sequence.mode === 'manual') {
    return sequence.items[baseIndex] ?? null;
  }

  const startedAt = sequence.startedAt ?? nowMs;
  const intervalMs = Math.max(500, sequence.intervalMs ?? 4000);
  const elapsedSteps = Math.max(0, Math.floor((nowMs - startedAt) / intervalMs));
  let nextIndex = baseIndex + elapsedSteps;

  if (sequence.loop !== false) {
    nextIndex %= sequence.items.length;
  } else if (nextIndex >= sequence.items.length) {
    nextIndex = sequence.items.length - 1;
  }

  return sequence.items[nextIndex] ?? null;
}

export function getToniChyronSequenceSelectedItemId(
  sequence: ToniChyronSequence,
  nowMs = Date.now()
): string | null {
  return getSelectedItem(sequence, nowMs)?.id ?? null;
}

function resolveSequenceRecursive(
  sequence: ToniChyronSequence,
  nowMs: number,
  depth: number,
  labels: string[]
): ToniChyronResolvedLeaf | null {
  if (depth > MAX_DEPTH) {
    return null;
  }

  const selected = getSelectedItem(sequence, nowMs);
  if (!selected) {
    return null;
  }

  if (selected.kind === 'sequence') {
    const nextLabels = [...labels, selected.label];
    return resolveSequenceRecursive(selected.sequence, nowMs, depth + 1, nextLabels);
  }

  return {
    text: selected.text,
    useMarquee: Boolean(selected.useMarquee),
    earoneSongId: selected.earoneSongId,
    earoneRank: selected.earoneRank,
    earoneSpins: selected.earoneSpins,
    externalChartId: selected.externalChartId,
    externalChartSongId: selected.externalChartSongId,
    externalChartRank: selected.externalChartRank,
    externalChartSpins: selected.externalChartSpins,
    activePathLabels: [...labels, selected.text]
  };
}

export function getToniChyronContentMode(
  contentMode: unknown,
  sequence: ToniChyronSequence | null
): ToniChyronContentMode {
  if (contentMode === 'text') {
    return 'text';
  }
  if (contentMode === 'sequence') {
    return 'sequence';
  }
  return sequence ? 'sequence' : 'text';
}

export function resolveToniChyronContent(config: {
  text?: string;
  useMarquee?: boolean;
  contentMode?: unknown;
  sequence?: unknown;
}, nowMs = Date.now()): ToniChyronResolvedContent {
  const normalizedSequence = normalizeToniChyronSequence(config.sequence);
  const contentMode = getToniChyronContentMode(config.contentMode, normalizedSequence);

  if (contentMode === 'sequence' && normalizedSequence) {
    const resolved = resolveSequenceRecursive(normalizedSequence, nowMs, 0, []);
    if (resolved) {
      return {
        text: resolved.text,
        useMarquee: resolved.useMarquee,
        source: 'sequence',
        activePathLabels: resolved.activePathLabels
      };
    }
  }

  return {
    text: typeof config.text === 'string' ? config.text : '',
    useMarquee: Boolean(config.useMarquee),
    source: 'text',
    activePathLabels: []
  };
}

export function resolveToniChyronLeaf(config: {
  contentMode?: unknown;
  sequence?: unknown;
}, nowMs = Date.now()): ToniChyronResolvedLeaf | null {
  const normalizedSequence = normalizeToniChyronSequence(config.sequence);
  const contentMode = getToniChyronContentMode(config.contentMode, normalizedSequence);

  if (contentMode !== 'sequence' || !normalizedSequence) {
    return null;
  }

  return resolveSequenceRecursive(normalizedSequence, nowMs, 0, []);
}

export function countSequenceLeafItems(sequence: ToniChyronSequence | null): number {
  if (!sequence) {
    return 0;
  }

  return sequence.items.reduce((count, item) => {
    if (item.kind === 'sequence') {
      return count + countSequenceLeafItems(item.sequence);
    }
    return count + 1;
  }, 0);
}

import { TIMEZONE_LINKS } from './timezoneAliases';

const FALLBACK_TIMEZONES = [
  'UTC',
  'America/Argentina/Buenos_Aires',
  'America/New_York',
  'America/Los_Angeles',
  'America/Mexico_City',
  'America/Sao_Paulo',
  'Europe/London',
  'Europe/Paris',
  'Europe/Madrid',
  'Asia/Tokyo',
  'Asia/Shanghai',
  'Australia/Sydney',
];

export function getSupportedTimezones(): string[] {
  const intlWithSupportedValuesOf = Intl as typeof Intl & {
    supportedValuesOf?: (key: 'timeZone') => string[];
  };

  try {
    const zones = intlWithSupportedValuesOf.supportedValuesOf?.('timeZone');
    if (zones && zones.length > 0) {
      return zones;
    }
  } catch {
    // Ignore and use fallback list.
  }

  return FALLBACK_TIMEZONES;
}

function parseOffsetToMinutes(offsetLabel: string): number {
  if (offsetLabel === 'GMT') return 0;

  const match = offsetLabel.match(/^GMT([+-])(\d{1,2})(?::?(\d{2}))?$/);
  if (!match) return 0;

  const sign = match[1] === '+' ? 1 : -1;
  const hours = Number(match[2]);
  const minutes = Number(match[3] || '0');
  return sign * (hours * 60 + minutes);
}

function getCityLabel(timezone: string): string {
  if (timezone === 'UTC') return 'UTC';

  const parts = timezone.split('/');
  const city = parts[parts.length - 1] || timezone;
  return city.replace(/_/g, ' ');
}

function getOffsetLabel(timezone: string, date: Date): string {
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      timeZoneName: 'shortOffset',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).formatToParts(date);

    const offset = parts.find((part) => part.type === 'timeZoneName')?.value;
    if (offset) {
      return offset.replace('UTC', 'GMT');
    }
  } catch {
    // Ignore and use fallback below.
  }

  return 'GMT';
}

export function getTimezoneOptionLabel(timezone: string, date: Date = new Date()): string {
  return `${getCityLabel(timezone)} (${getOffsetLabel(timezone, date)})`;
}

export function getTimezonesSortedByOffset(date: Date = new Date()): string[] {
  const timezones = getSupportedTimezones();

  const withMeta = timezones.map((timezone) => {
    const offsetLabel = getOffsetLabel(timezone, date);
    return {
      timezone,
      offsetMinutes: parseOffsetToMinutes(offsetLabel),
      label: `${getCityLabel(timezone)} (${offsetLabel})`,
    };
  });

  withMeta.sort((a, b) => {
    if (a.offsetMinutes !== b.offsetMinutes) {
      return a.offsetMinutes - b.offsetMinutes;
    }
    return a.label.localeCompare(b.label);
  });

  return withMeta.map((item) => item.timezone);
}

export interface TimezoneOption {
  value: string;
  label: string;
}

/**
 * Replaces the options at `indexes` (all the same zone) with one option for
 * the saved id, in the first one's place. A saved id that names a city keeps
 * its own name (Kyiv, not Kiev); a POSIX id such as EST5EDT keeps the listed
 * city's label.
 */
function withSavedOption(options: TimezoneOption[], indexes: number[], value: string, date: Date): TimezoneOption[] {
  const [first] = indexes;
  const label = value.includes('/') ? getTimezoneOptionLabel(value, date) : options[first].label;
  return options.flatMap((option, index) =>
    index === first ? [{ value, label }] : indexes.includes(index) ? [] : [option]
  );
}

/** The tz database zone that `timezone` names, through its links. */
function getLinkedZone(timezone: string): string {
  return TIMEZONE_LINKS[timezone] ?? timezone;
}

/**
 * The browser's own id for `timezone`: Intl resolves an alias such as
 * America/Argentina/Buenos_Aires to the name it lists (America/Buenos_Aires
 * in Chromium). Used only to compare ids; it is never stored. An id the
 * browser does not know is returned unchanged.
 */
function getBrowserTimezoneId(timezone: string): string {
  try {
    return new Intl.DateTimeFormat('en-US', { timeZone: timezone }).resolvedOptions().timeZone;
  } catch {
    return timezone;
  }
}

/**
 * Returns the picker options with `value` kept selectable as exactly one
 * option. The options list the zones the browser's Intl reports, which may
 * spell a saved or default zone differently (Chromium lists
 * America/Buenos_Aires and Asia/Calcutta for the saved
 * America/Argentina/Buenos_Aires and Asia/Kolkata). The option for the same
 * zone then carries the saved id, and its name when the id names a city, so
 * the picker shows it selected and saving keeps the stored id. Ids are
 * matched through Intl first and then through the tz database's links
 * (TIMEZONE_LINKS), for engines such as WebKit whose Intl links neither
 * spelling. A zone the list lacks under any name is listed first. The saved
 * id is never rewritten.
 */
export function withTimezoneOption(options: TimezoneOption[], value: string, date: Date = new Date()): TimezoneOption[] {
  if (!value || options.some((option) => option.value === value)) {
    return options;
  }
  const browserId = getBrowserTimezoneId(value);
  const aliasIndex = options.findIndex((option) => option.value === browserId);
  if (aliasIndex >= 0) {
    return withSavedOption(options, [aliasIndex], value, date);
  }
  // Intl linked nothing (WebKit resolves both spellings to themselves):
  // compare through the tz database's links instead. Every listed name of
  // the saved zone becomes the one saved option.
  const zone = getLinkedZone(value);
  const sameZone = options.flatMap((option, index) => (getLinkedZone(option.value) === zone ? [index] : []));
  if (sameZone.length > 0) {
    return withSavedOption(options, sameZone, value, date);
  }
  return [{ value, label: getTimezoneOptionLabel(value, date) }, ...options];
}

function formatHostForUrl(hostname: string): string {
  if (!hostname) {
    return '127.0.0.1';
  }

  // Bracket IPv6 hosts when building URLs like http://[::1]:3000
  return hostname.includes(':') ? `[${hostname}]` : hostname;
}

function getDevDefaultApiBaseUrl(): string {
  if (typeof window === 'undefined') {
    return 'http://127.0.0.1:3000';
  }

  const host = formatHostForUrl(window.location.hostname);
  return `http://${host}:3000`;
}

export const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || (import.meta.env.DEV ? getDevDefaultApiBaseUrl() : undefined);

export function getApiBaseUrl(): string {
  if (!API_BASE_URL) {
    throw new Error('VITE_API_BASE_URL must be set for frontend API requests.');
  }

  return API_BASE_URL.replace(/\/$/, '');
}

export function apiUrl(path: string): string {
  const normalizedPath = path.startsWith('/') ? path : `/${path}`;
  return `${getApiBaseUrl()}${normalizedPath}`;
}

export interface GlobalTimeOverride {
  startTime: string;
  startedAt: string;
}

interface ClockParts {
  hours: number;
  minutes: number;
  seconds: number;
}

function parseStartTime(startTime: string): ClockParts | null {
  const match = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(startTime.trim());
  if (!match) {
    return null;
  }

  return {
    hours: Number(match[1]),
    minutes: Number(match[2]),
    seconds: 0,
  };
}

export function getOverrideClockParts(
  override: GlobalTimeOverride,
  now: Date = new Date(),
): ClockParts | null {
  const parsed = parseStartTime(override.startTime);
  if (!parsed) {
    return null;
  }

  const startedAtMillis = new Date(override.startedAt).getTime();
  if (!Number.isFinite(startedAtMillis)) {
    return null;
  }

  const startSeconds = parsed.hours * 3600 + parsed.minutes * 60;
  const elapsedSeconds = Math.max(
    0,
    Math.floor((now.getTime() - startedAtMillis) / 1000),
  );
  const totalSeconds = (startSeconds + elapsedSeconds) % 86400;

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  return { hours, minutes, seconds };
}

export function formatClockParts(parts: ClockParts): string {
  const hours = String(parts.hours).padStart(2, '0');
  const minutes = String(parts.minutes).padStart(2, '0');
  return `${hours}:${minutes}`;
}

/**
 * A song Palazzo could not load (`song_request_failed`, gaulatti/alcantara#175):
 * the operator's one-line notice, or null for anything else.
 */
export function songRequestFailureNotice(event: unknown): string | null {
  if (!event || typeof event !== "object") return null;
  const e = event as Record<string, unknown>;
  if (e.type !== "song_request_failed") return null;
  const title =
    typeof e.title === "string" && e.title.trim() ? e.title.trim() : "A song";
  const artist =
    typeof e.artist === "string" && e.artist.trim() ? ` by ${e.artist.trim()}` : "";
  const reason =
    e.reason === "timeout" ? "it took too long to load" : "it could not be loaded";
  return `“${title}”${artist} did not play: ${reason}. The next song played instead.`;
}

export type StageSceneResponse = {
  stagedSceneId?: unknown;
  stagedScene?: unknown;
  version?: unknown;
};

export type AcceptedStageSceneResponse<TScene extends object> = {
  stagedSceneId: number | null;
  stagedScene: TScene | null;
};

type AcceptControlUpdate = (payload: unknown, topicOverride: 'state') => boolean;

export function acceptStageSceneResponse<TScene extends object>(
  result: StageSceneResponse,
  acceptControlUpdate: AcceptControlUpdate,
): AcceptedStageSceneResponse<TScene> | null {
  if (!acceptControlUpdate(result, 'state')) {
    return null;
  }

  return {
    stagedSceneId:
      typeof result.stagedSceneId === 'number' && Number.isFinite(result.stagedSceneId)
        ? result.stagedSceneId
        : null,
    stagedScene:
      result.stagedScene && typeof result.stagedScene === 'object'
        ? (result.stagedScene as TScene)
        : null,
  };
}

import { getApiBaseUrl } from './apiBaseUrl';

export type ProgramRealtimeRole = 'program' | 'control';

export function getProgramRealtimeSocketUrl(
  programId: string,
  role: ProgramRealtimeRole,
  ticket?: string | null,
): string {
  const socketUrl = new URL('/program/ws', getApiBaseUrl());
  socketUrl.protocol = socketUrl.protocol === 'https:' ? 'wss:' : 'ws:';
  socketUrl.searchParams.set('programId', programId);
  socketUrl.searchParams.set('role', role);
  if (ticket) socketUrl.searchParams.set('ticket', ticket);
  return socketUrl.toString();
}

export interface SlideshowSceneLike {
  layout?: { componentType?: string | null } | null;
  metadata?: string | null;
}

function normalizeMediaGroupId(value: unknown): number | null {
  const numeric = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0 || !Number.isInteger(numeric)) {
    return null;
  }
  return numeric;
}

function slideshowProps(scene: SlideshowSceneLike | null | undefined): Record<string, unknown> | null {
  const componentTypes = scene?.layout?.componentType
    ?.split(',')
    .map((componentType) => componentType.trim())
    .filter(Boolean) ?? [];
  if (!componentTypes.includes('slideshow')) return null;

  try {
    const metadata = scene?.metadata ? JSON.parse(scene.metadata) : {};
    if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return null;
    const slideshow = (metadata as Record<string, unknown>).slideshow;
    return slideshow && typeof slideshow === 'object' && !Array.isArray(slideshow)
      ? (slideshow as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

export function getSceneSlideshowLabelId(scene: SlideshowSceneLike | null | undefined): string | null {
  const props = slideshowProps(scene);
  if (!props) return null;
  const labelId = props.labelId;
  if (typeof labelId === 'string' && labelId.trim()) return labelId.trim();
  const legacyMediaGroupId = normalizeMediaGroupId(props.mediaGroupId);
  return legacyMediaGroupId === null ? null : `legacy-media-group:${legacyMediaGroupId}`;
}

export function getSceneSlideshowMediaGroupId(scene: SlideshowSceneLike | null | undefined): number | null {
  const props = slideshowProps(scene);
  return props ? normalizeMediaGroupId(props.mediaGroupId) : null;
}

export function getProgramSlideshowMediaGroupIds(
  activeScene: SlideshowSceneLike | null | undefined,
  stagedScene: SlideshowSceneLike | null | undefined
): number[] {
  const ids = [getSceneSlideshowMediaGroupId(activeScene), getSceneSlideshowMediaGroupId(stagedScene)];
  return [...new Set(ids.filter((id): id is number => id !== null))];
}

export function getProgramSlideshowLabelIds(
  activeScene: SlideshowSceneLike | null | undefined,
  stagedScene: SlideshowSceneLike | null | undefined
): string[] {
  const ids = [getSceneSlideshowLabelId(activeScene), getSceneSlideshowLabelId(stagedScene)];
  return [...new Set(ids.filter((id): id is string => id !== null))];
}

import { useCallback } from "react";
import { useConsolePreferences } from "../contexts/ConsolePreferencesContext";

export function useGlobalTransitionId(programId = "main") {
  const { profile, updateProfile } = useConsolePreferences();
  const normalizedProgramId = programId.trim() || "main";
  const transitionId =
    profile.transitions[normalizedProgramId] || "crescendo-prism";
  const setTransitionId = useCallback(
    (value: string) => {
      updateProfile({
        transitions: {
          ...profile.transitions,
          [normalizedProgramId]: value.trim() || "crescendo-prism",
        },
      });
    },
    [normalizedProgramId, profile.transitions, updateProfile],
  );
  return [transitionId, setTransitionId] as const;
}

import { useCallback } from "react";
import { useConsolePreferences } from "../contexts/ConsolePreferencesContext";

export function useGlobalProgramId() {
  const { profile, updateProfile } = useConsolePreferences();
  const setProgramId = useCallback(
    (value: string) => {
      updateProfile({ selectedProgramId: value.trim() || "main" });
    },
    [updateProfile],
  );
  return [profile.selectedProgramId, setProgramId] as const;
}

import { apiUrl } from './apiBaseUrl';
import type { ChartValues } from './programChartValues';

/**
 * Provider-neutral chart feed, refreshed by the backend from the chart
 * upstream every 15 seconds. It is the program page's only chart source.
 */
export const CHART_FEED_URL = apiUrl('/charts/realtime');

/** One entry of `GET /charts/realtime`. */
export interface ChartFeedEntry {
  provider: string;
  externalId: string | null;
  title: string;
  artist: string;
  rank: string | null;
  spins: string | null;
  updatedAt: string;
}

/** Entries by chart id and by match key, the first entry winning a shared key. */
export interface ChartFeedLookup {
  byId: Record<string, ChartFeedEntry>;
  byKey: Record<string, ChartFeedEntry>;
  updatedAt: string | null;
}

/** The text normalization chart matching has always used (and the backend uses for its keys). */
export function normalizeChartText(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** An entry's match key: normalized artist, then normalized title, as the backend builds it. */
export function chartEntryKey(artist: string, title: string): string {
  return [normalizeChartText(artist), normalizeChartText(title)].filter(Boolean).join(' ');
}

/** Finds an entry by chart id, else by the chyron text normalized to a match key. */
export function matchChartEntry<Entry>(
  lookup: { byId: Record<string, Entry>; byKey: Record<string, Entry> } | null,
  options: { id?: string | null; text?: string | null }
): Entry | null {
  if (!lookup) {
    return null;
  }
  const id = typeof options.id === 'string' && options.id.trim() ? options.id.trim() : null;
  if (id && lookup.byId[id]) {
    return lookup.byId[id];
  }
  const key = typeof options.text === 'string' && options.text.trim() ? normalizeChartText(options.text) : '';
  if (key && lookup.byKey[key]) {
    return lookup.byKey[key];
  }
  return null;
}

function optionalText(value: unknown): string | null {
  return typeof value === 'string' && value ? value : null;
}

/** Builds the lookup from a feed payload, or returns null when the payload is not a feed. */
export function buildChartFeedLookup(payload: unknown): ChartFeedLookup | null {
  if (!Array.isArray(payload)) {
    return null;
  }
  const lookup: ChartFeedLookup = { byId: {}, byKey: {}, updatedAt: null };
  for (const item of payload as Array<Partial<ChartFeedEntry> | null>) {
    if (!item || typeof item.artist !== 'string' || typeof item.title !== 'string') {
      continue;
    }
    const key = chartEntryKey(item.artist, item.title);
    if (!key || !item.artist || !item.title) {
      continue;
    }
    const entry: ChartFeedEntry = {
      provider: optionalText(item.provider) ?? '',
      externalId: optionalText(item.externalId),
      title: item.title,
      artist: item.artist,
      rank: optionalText(item.rank),
      spins: optionalText(item.spins),
      updatedAt: optionalText(item.updatedAt) ?? ''
    };
    lookup.updatedAt = lookup.updatedAt ?? optionalText(item.updatedAt);
    if (entry.externalId) {
      lookup.byId[entry.externalId] = entry;
    }
    if (!lookup.byKey[key]) {
      lookup.byKey[key] = entry;
    }
  }
  return lookup;
}

/**
 * The page's chart lookup from the feed. A feed that does not answer, answers
 * with an error or does not return a list is an error for the caller to report;
 * the page then keeps the last lookup it loaded.
 */
export async function loadChartLookup(fetchImpl: typeof fetch = fetch): Promise<ChartFeedLookup> {
  const res = await fetchImpl(CHART_FEED_URL);
  if (!res.ok) {
    throw new Error(`HTTP ${res.status}`);
  }
  const lookup = buildChartFeedLookup(await res.json());
  if (!lookup) {
    throw new Error('The chart feed did not return a list');
  }
  return lookup;
}

/** Rank and spins for a chyron item from the loaded feed. */
export function realtimeChartValues(lookup: ChartFeedLookup | null, options: { id?: string | null; text?: string | null }): ChartValues | null {
  const entry = matchChartEntry(lookup, options);
  return entry ? { rank: entry.rank, spins: entry.spins } : null;
}

